insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('dd000000-0000-0000-0000-000000000001', 'mrcp2', 'cb85389a-bbdc-4d36-9ba9-1a4f33e71421',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('dd000000-0000-0000-0000-000000000001', 'A', 'Delay the scan until N-acetylcysteine has been given for 48 hours', false, 'Ruled out because N-acetylcysteine has not been shown to reliably reduce contrast-associated AKI or hard outcomes in trials, and delaying a time-critical CT pulmonary angiogram for suspected PE risks missing a life-threatening diagnosis.', 1),
('dd000000-0000-0000-0000-000000000001', 'B', 'Proceed with the scan using standard contrast volume with no additional measures, as diabetic nephropathy does not increase contrast risk', false, 'Ruled out because CKD (especially with diabetes) is the principal risk factor for contrast-associated AKI, and periprocedural hydration is indicated in this high-risk patient.', 2),
('dd000000-0000-0000-0000-000000000001', 'C', 'Give intravenous isotonic crystalloid before and after the scan, and temporarily withhold metformin and ramipril around the procedure', true, 'Correct. Peri-procedural isotonic saline volume expansion is the most evidence-supported measure to reduce contrast-associated AKI risk in high-risk patients; metformin should be withheld around contrast exposure because of lactic acidosis risk if AKI occurs, and RAAS blockade is often held peri-procedurally in volume-uncertain high-risk patients, though the scan itself should not be delayed given the clinical urgency.', 3),
('dd000000-0000-0000-0000-000000000001', 'D', 'Arrange prophylactic haemodialysis immediately after the contrast study', false, 'Ruled out because prophylactic dialysis to remove contrast has not been shown to prevent contrast-associated AKI and is not indicated for this level of renal impairment.', 4),
('dd000000-0000-0000-0000-000000000001', 'E', 'Substitute gadolinium-based contrast for iodinated contrast to reduce nephrotoxicity', false, 'Ruled out because gadolinium is not used for CT angiography, and gadolinium itself carries nephrogenic systemic fibrosis risk in advanced CKD; it is not a nephroprotective substitute here.', 5),
('dd000000-0000-0000-0000-000000000002', 'A', 'Continue aggressive intravenous fluids alone and reassess in 24 hours before considering dialysis', false, 'Ruled out because the patient is already oliguric with life-threatening hyperkalaemia despite fluids; further delay risks arrhythmia and cardiac arrest, and continued fluid loading in an oliguric anuric-trending patient risks pulmonary oedema.', 1),
('dd000000-0000-0000-0000-000000000002', 'B', 'Administer intravenous sodium bicarbonate to alkalinise the urine as the priority intervention', false, 'Ruled out because urinary alkalinisation for myoglobin clearance is of unproven benefit and is not the priority when severe hyperkalaemia with oliguric AKI already mandates dialysis; bicarbonate can also worsen hypocalcaemia in rhabdomyolysis.', 2),
('dd000000-0000-0000-0000-000000000002', 'C', 'Give a loop diuretic to force diuresis and avoid the need for dialysis', false, 'Ruled out because forced diuresis with loop diuretics has no proven benefit in rhabdomyolysis-associated AKI, does not correct hyperkalaemia, and may worsen intravascular volume depletion.', 3),
('dd000000-0000-0000-0000-000000000002', 'D', 'Start oral calcium resonium and review potassium again in 24 hours', false, 'Ruled out because calcium resonium acts too slowly and unreliably to manage severe hyperkalaemia in the context of oliguric AKI; this needs definitive extracorporeal removal, not a slow cation exchanger.', 4),
('dd000000-0000-0000-0000-000000000002', 'E', 'Arrange urgent renal replacement therapy in view of severe hyperkalaemia with oliguric AKI', true, 'Correct. Hyperkalaemia at 6.8 mmol/L with oliguria despite adequate volume resuscitation in established rhabdomyolysis-induced AKI is an indication for urgent renal replacement therapy; medical hyperkalaemia treatment (insulin-dextrose, calcium, salbutamol) is a temporising bridge but does not remove potassium or myoglobin, and dialysis should not be delayed.', 5),
('dd000000-0000-0000-0000-000000000003', 'A', 'Perform urgent large-volume paracentesis without albumin cover to relieve abdominal pressure on the kidneys', false, 'Ruled out because large-volume paracentesis without albumin replacement risks worsening circulatory dysfunction and precipitating further renal impairment (paracentesis-induced circulatory dysfunction), the opposite of what is needed.', 1),
('dd000000-0000-0000-0000-000000000003', 'B', 'Start broad-spectrum antibiotics empirically for presumed spontaneous bacterial peritonitis without further evaluation', false, 'Ruled out because blood cultures are negative and there is no stated evidence of infection; while SBP must always be excluded (ideally via diagnostic ascitic tap) before diagnosing HRS, empirical antibiotics are not the specific next management step once infection has been reasonably excluded and the picture fits HRS-AKI.', 2),
('dd000000-0000-0000-0000-000000000003', 'C', 'Refer for immediate haemodialysis as the definitive treatment for hepatorenal syndrome', false, 'Ruled out because renal replacement therapy is reserved for cases refractory to vasoconstrictor-albumin therapy or as a bridge to transplantation, not as first-line treatment for HRS-AKI.', 3),
('dd000000-0000-0000-0000-000000000003', 'D', 'Start terlipressin combined with continued intravenous albumin', true, 'Correct. This presentation is consistent with hepatorenal syndrome-acute kidney injury (HRS-AKI), diagnosed after excluding structural renal disease, sepsis, and volume-responsive prerenal AKI (no response to albumin challenge and diuretic withdrawal). First-line pharmacological treatment is a splanchnic vasoconstrictor, terlipressin, combined with ongoing albumin, which improves renal perfusion by reducing splanchnic vasodilation and effective arterial underfilling.', 4),
('dd000000-0000-0000-0000-000000000003', 'E', 'Stop albumin and switch to a loop diuretic to increase urine output', false, 'Ruled out because HRS-AKI is a functional, haemodynamically-mediated form of AKI unresponsive to diuretics, and diuretics would worsen effective circulating volume and renal perfusion.', 5),
('dd000000-0000-0000-0000-000000000004', 'A', 'Give intravenous calcium gluconate immediately, followed by insulin-dextrose and arrangement of urgent dialysis', true, 'Correct. ECG changes of severe hyperkalaemia (widened QRS, loss of P waves) indicate imminent risk of a fatal arrhythmia; intravenous calcium should be given immediately to stabilise the myocardium, followed promptly by insulin-dextrose to shift potassium intracellularly, with urgent renal replacement therapy arranged since the underlying oliguric AKI means potassium will not be definitively cleared without dialysis.', 1),
('dd000000-0000-0000-0000-000000000004', 'B', 'Give nebulised salbutamol alone and recheck the potassium in one hour before further action', false, 'Ruled out because salbutamol alone is insufficient in the presence of ECG changes signalling imminent arrhythmia risk; calcium for membrane stabilisation must be given immediately, and definitive potassium removal via dialysis should be arranged without delay.', 2),
('dd000000-0000-0000-0000-000000000004', 'C', 'Start oral calcium resonium and observe on the ward', false, 'Ruled out because calcium resonium acts far too slowly to address ECG changes indicating imminent risk of cardiac arrest, and does not substitute for emergency stabilisation and dialysis.', 3),
('dd000000-0000-0000-0000-000000000004', 'D', 'Administer intravenous sodium bicarbonate as the sole emergency measure', false, 'Ruled out because bicarbonate is not first-line for acute stabilisation of hyperkalaemic ECG changes (its effect is slow and evidence is weak without significant acidosis); calcium gluconate is the priority for membrane stabilisation.', 4),
('dd000000-0000-0000-0000-000000000004', 'E', 'Withhold treatment until formal renal replacement therapy can be arranged over the next few hours', false, 'Ruled out because ECG changes signal an immediately life-threatening state; medical stabilisation with calcium and insulin-dextrose must occur without delay while dialysis is being organised, not instead of it.', 5),
('dd000000-0000-0000-0000-000000000005', 'A', 'Fractional excretion of sodium', false, 'Ruled out because this patient is on a loop diuretic, which independently increases urinary sodium excretion and invalidates the fractional excretion of sodium as a discriminator between prerenal AKI and ATN in this context.', 1),
('dd000000-0000-0000-0000-000000000005', 'B', 'Fractional excretion of urea', true, 'Correct. In patients on diuretics, the fractional excretion of sodium is unreliable because diuretics cause natriuresis regardless of renal perfusion status. The fractional excretion of urea is less affected by diuretic use and remains a more reliable marker for distinguishing prerenal AKI (low fractional excretion of urea, reflecting preserved tubular reabsorptive capacity) from acute tubular necrosis (higher fractional excretion of urea, reflecting tubular dysfunction).', 2),
('dd000000-0000-0000-0000-000000000005', 'C', 'Renal ultrasound with Doppler assessment of resistive indices', false, 'Ruled out because renal Doppler resistive indices are not a validated or reliable bedside method for distinguishing prerenal AKI from ATN in routine clinical practice; ultrasound here is more useful to exclude obstruction.', 3),
('dd000000-0000-0000-0000-000000000005', 'D', 'Urine microscopy for eosinophils', false, 'Ruled out because urinary eosinophils are classically associated with acute interstitial nephritis, not with distinguishing prerenal azotaemia from ATN.', 4),
('dd000000-0000-0000-0000-000000000005', 'E', 'Spot urine protein:creatinine ratio', false, 'Ruled out because proteinuria quantification is not the relevant discriminator between prerenal AKI and ATN; it is more useful for characterising glomerular disease.', 5),
('dd000000-0000-0000-0000-000000000006', 'A', 'Stop all diuretics immediately because rising creatinine indicates diuretic-induced prerenal AKI requiring fluid resuscitation', false, 'Ruled out because the patient remains clinically congested (raised JVP, crepitations, oedema); a rising creatinine in this context reflects cardiorenal physiology (venous congestion and reduced renal perfusion pressure) rather than volume depletion, and giving fluids would worsen congestion.', 1),
('dd000000-0000-0000-0000-000000000006', 'B', 'Add a thiazide-type diuretic (sequential nephron blockade) to the loop diuretic and reassess response', true, 'Correct. In diuretic-resistant congestion, sequential nephron blockade by adding a distal-acting thiazide or thiazide-like diuretic (e.g. metolazone) to a loop diuretic is an established, evidence-based strategy to overcome resistance caused by compensatory distal tubular sodium reabsorption, and should be trialled before considering extracorporeal ultrafiltration.', 2),
('dd000000-0000-0000-0000-000000000006', 'C', 'Proceed directly to isolated ultrafiltration without first trialling combination/sequential diuretic therapy', false, 'Ruled out because trials (e.g. CARRESS-HF) have shown that a stepped pharmacological diuretic strategy is generally preferred over early ultrafiltration, which has not shown superior outcomes and carries additional procedural risk; ultrafiltration is reserved for cases truly refractory to optimised medical therapy.', 3),
('dd000000-0000-0000-0000-000000000006', 'D', 'Switch furosemide to an ACE inhibitor as the primary decongestive strategy', false, 'Ruled out because ACE inhibitors are not diuretics and would not address ongoing volume overload; in this setting of rising creatinine and congestion, introducing or up-titrating RAAS blockade acutely could worsen renal perfusion further.', 4),
('dd000000-0000-0000-0000-000000000006', 'E', 'Perform urgent renal biopsy to characterise the cause of the creatinine rise', false, 'Ruled out because the clinical picture is classic cardiorenal syndrome from venous congestion in decompensated heart failure; biopsy is not indicated and would not change immediate management.', 5),
('dd000000-0000-0000-0000-000000000007', 'A', 'Increase the dose of the vitamin D receptor activator to further suppress PTH', false, 'Ruled out because the vitamin D receptor activator was stopped due to hypercalcaemia; increasing it would worsen hypercalcaemia further and is contraindicated in this context.', 1),
('dd000000-0000-0000-0000-000000000007', 'B', 'Increase the dose of calcium-based phosphate binders to further control phosphate', false, 'Ruled out because the patient is already hypercalcaemic; calcium-based binders would add to the calcium load and are inappropriate here. A non-calcium-based binder would be preferred if phosphate control needs escalation.', 2),
('dd000000-0000-0000-0000-000000000007', 'C', 'Start the calcimimetic cinacalcet', true, 'Correct. In severe secondary hyperparathyroidism with hypercalcaemia, a calcimimetic (cinacalcet, or etelcalcetide in dialysis patients) is preferred over vitamin D receptor activators because it lowers PTH while also lowering (or not raising) serum calcium and phosphate, unlike vitamin D analogues which can worsen hypercalcaemia and hyperphosphataemia.', 3),
('dd000000-0000-0000-0000-000000000007', 'D', 'Proceed directly to parathyroidectomy without a trial of medical therapy', false, 'Ruled out because although nodular hyperplasia and very high PTH may eventually require parathyroidectomy if refractory, a trial of calcimimetic therapy is the appropriate next step before proceeding to surgery, which is reserved for medically refractory cases.', 4),
('dd000000-0000-0000-0000-000000000007', 'E', 'Stop all phosphate binders since PTH is now the dominant problem', false, 'Ruled out because phosphate remains significantly elevated and stopping binders would worsen hyperphosphataemia, further stimulating PTH secretion and worsening CKD-MBD.', 5),
('dd000000-0000-0000-0000-000000000008', 'A', 'Give intravenous iron despite the elevated ferritin, as the low transferrin saturation indicates functional iron deficiency', true, 'Correct. In CKD, ferritin is an unreliable marker of true iron stores because it is elevated by the chronic inflammatory state; a low transferrin saturation (<20%) despite high ferritin indicates functional iron deficiency (iron is present but not readily mobilisable), which limits ESA response. Intravenous iron (rather than oral, which is poorly absorbed in CKD/inflammation) is indicated and should improve ESA responsiveness.', 1),
('dd000000-0000-0000-0000-000000000008', 'B', 'Withhold iron because ferritin is already elevated, and increase the ESA dose further', false, 'Ruled out because increasing ESA dose without addressing functional iron deficiency is unlikely to be effective and increases risks of ESA therapy (hypertension, thrombosis); the transferrin saturation indicates a need for iron repletion despite the ferritin level.', 2),
('dd000000-0000-0000-0000-000000000008', 'C', 'Switch to oral iron supplementation as first-line therapy', false, 'Ruled out because oral iron absorption is impaired in CKD, partly due to elevated hepcidin from chronic inflammation, making intravenous iron more effective in this setting.', 3),
('dd000000-0000-0000-0000-000000000008', 'D', 'Arrange bone marrow biopsy to investigate the anaemia', false, 'Ruled out because the anaemia is adequately explained by CKD with functional iron deficiency and ESA hyporesponsiveness; invasive marrow sampling is not indicated as a next step.', 4),
('dd000000-0000-0000-0000-000000000008', 'E', 'Transfuse packed red cells electively to correct the haemoglobin', false, 'Ruled out because there is no indication of acute or symptomatic anaemia mandating transfusion, and this does not address the underlying reversible functional iron deficiency; transfusion also carries sensitisation risk relevant to future transplant candidacy.', 5),
('dd000000-0000-0000-0000-000000000009', 'A', 'Add a second RAAS-blocking agent (angiotensin receptor blocker) in combination with the ACE inhibitor', false, 'Ruled out because dual RAAS blockade (ACE inhibitor plus ARB) increases the risk of hyperkalaemia and AKI without proven additional renoprotective benefit, and is generally avoided in current practice.', 1),
('dd000000-0000-0000-0000-000000000009', 'B', 'Stop the ACE inhibitor because albuminuria has not resolved', false, 'Ruled out because RAAS blockade remains foundational therapy for diabetic kidney disease regardless of residual albuminuria, and should be continued, not stopped.', 2),
('dd000000-0000-0000-0000-000000000009', 'C', 'Increase blood pressure targets to allow higher-dose diuretic therapy', false, 'Ruled out because blood pressure is already well controlled, and loosening BP targets would not address the albuminuria or provide the renoprotection achieved by add-on SGLT2 inhibition.', 3),
('dd000000-0000-0000-0000-000000000009', 'D', 'Refer for renal biopsy to confirm diabetic nephropathy before further treatment', false, 'Ruled out because the clinical picture (longstanding diabetes, proportionate proteinuria, gradually reduced eGFR) is typical for diabetic kidney disease, and biopsy is not required before escalating evidence-based therapy.', 4),
('dd000000-0000-0000-0000-000000000009', 'E', 'Add an SGLT2 inhibitor', true, 'Correct. In patients with diabetic CKD and significant albuminuria already on maximally tolerated RAAS blockade, adding an SGLT2 inhibitor provides additional, mechanistically distinct renoprotection (reducing intraglomerular pressure via tubuloglomerular feedback, among other effects) and has been shown in trials (e.g. CREDENCE, DAPA-CKD) to slow progression of CKD and reduce cardiovascular events, independent of glycaemic effect.', 5),
('dd000000-0000-0000-0000-000000000010', 'A', 'Osteitis fibrosa cystica due to severe secondary hyperparathyroidism; increase the vitamin D receptor activator dose', false, 'Ruled out because osteitis fibrosa is characterised by elevated, not suppressed, PTH with high bone turnover; increasing vitamin D receptor activator would further suppress PTH and worsen adynamic bone disease in this patient.', 1),
('dd000000-0000-0000-0000-000000000010', 'B', 'Osteomalacia due to vitamin D deficiency; increase native vitamin D supplementation', false, 'Ruled out because the biochemical picture (suppressed PTH, hypercalcaemia, low bone turnover markers) fits adynamic bone disease from oversuppression rather than nutritional vitamin D deficiency, and further vitamin D receptor activation would worsen the problem.', 2),
('dd000000-0000-0000-0000-000000000010', 'C', 'Aluminium bone disease; start desferrioxamine chelation therapy', false, 'Ruled out because there is no history of aluminium exposure (historically from aluminium-containing phosphate binders or dialysate) suggested in this vignette, and chelation is not the appropriate first step here.', 3),
('dd000000-0000-0000-0000-000000000010', 'D', 'Adynamic bone disease; reduce or stop the vitamin D receptor activator and calcium-based binders to allow PTH to rise towards target', true, 'Correct. A suppressed PTH, hypercalcaemia, low bone turnover markers, and fragility fractures in a dialysis patient are characteristic of adynamic bone disease, typically caused by oversuppression of PTH from excessive vitamin D receptor activator and calcium loading. Management involves reducing calcium load and vitamin D receptor activator dosing to allow PTH to rise into an appropriate target range, which restores bone turnover.', 4),
('dd000000-0000-0000-0000-000000000010', 'E', 'Multiple myeloma with lytic bone disease; arrange serum and urine electrophoresis before any medication changes', false, 'Ruled out because the biochemical pattern (suppressed PTH, hypercalcaemia, low turnover markers) in a long-term dialysis patient on vitamin D receptor activator and calcium-based binders is much more consistent with adynamic bone disease than myeloma, although myeloma should always remain a differential to keep in mind if the picture were atypical.', 5),
('dd000000-0000-0000-0000-000000000011', 'A', 'Offer conservative kidney management with symptom-focused supportive care, without initiating dialysis', true, 'Correct. In frail elderly patients with multiple comorbidities and a clearly expressed preference to avoid invasive treatment, conservative kidney management (active symptom control, advance care planning, and supportive care without dialysis) is an appropriate, evidence-based pathway, as dialysis in this population often does not improve survival or quality of life and may impose significant burden.', 1),
('dd000000-0000-0000-0000-000000000011', 'B', 'Proceed immediately to arteriovenous fistula formation in preparation for haemodialysis regardless of stated preferences', false, $x$Ruled out because this disregards the patient's expressed wishes and the evidence that dialysis may not benefit survival or quality of life in very frail elderly patients with extensive comorbidity; shared decision-making should guide the plan.$x$, 2),
('dd000000-0000-0000-0000-000000000011', 'C', 'Insert a peritoneal dialysis catheter urgently as PD is always preferred in frail elderly patients', false, $x$Ruled out because there is no current uraemic emergency, and initiating any dialysis modality contradicts the patient's clearly stated preference and the appropriateness of a conservative pathway in this context.$x$, 3),
('dd000000-0000-0000-0000-000000000011', 'D', 'Refer for renal transplant work-up as the most durable long-term option', false, 'Ruled out because transplantation is not appropriate given the severe frailty, advanced dementia, and multiple comorbidities, which are significant contraindications to major surgery and lifelong immunosuppression.', 4),
('dd000000-0000-0000-0000-000000000011', 'E', 'Delay any decision-making until a uraemic emergency forces urgent dialysis', false, 'Ruled out because proactive shared decision-making and advance care planning, rather than reactive crisis management, is the recommended approach in advanced CKD, particularly when conservative management is being considered.', 5),
('dd000000-0000-0000-0000-000000000012', 'A', 'Increase the dose of calcium carbonate to control phosphate more aggressively', false, 'Ruled out because this would add further calcium load in a patient who already has vascular calcification and calcium at the upper limit of normal, increasing the risk of worsening cardiovascular calcification.', 1),
('dd000000-0000-0000-0000-000000000012', 'B', 'Add or switch to a non-calcium-based binder such as lanthanum carbonate rather than a calcium-based binder', true, 'Correct. Given established vascular calcification and calcium already at the upper limit of normal, adding further calcium load via calcium-based binders would increase cardiovascular calcification risk; a non-calcium-based binder (lanthanum carbonate, or sevelamer if not already maximised) is preferred to control phosphate while minimising calcium burden.', 2),
('dd000000-0000-0000-0000-000000000012', 'C', 'Switch to aluminium hydroxide as a first-line long-term binder', false, 'Ruled out because aluminium-containing binders carry a risk of chronic aluminium toxicity (osteomalacia, encephalopathy) with long-term use and are not recommended as first-line, long-term therapy.', 3),
('dd000000-0000-0000-0000-000000000012', 'D', 'Discontinue all phosphate binders since dietary counselling has already been given', false, 'Ruled out because phosphate remains significantly elevated despite dietary measures, and stopping binders would allow further uncontrolled hyperphosphataemia, worsening CKD-MBD and vascular calcification risk.', 4),
('dd000000-0000-0000-0000-000000000012', 'E', 'Increase dialysis session frequency alone without adjusting binder therapy', false, 'Ruled out because while more frequent or longer dialysis can help phosphate clearance, binder therapy optimisation is the primary and more immediately actionable strategy here, and this option ignores the calcium-load concern that needs addressing.', 5),
('dd000000-0000-0000-0000-000000000013', 'A', 'Continue omeprazole and start empirical antibiotics for presumed pyelonephritis', false, 'Ruled out because sterile pyuria with eosinophilia and normal imaging in the context of a known nephrotoxic/allergic drug exposure points away from bacterial pyelonephritis towards drug-induced interstitial nephritis; continuing the causative drug would perpetuate renal injury.', 1),
('dd000000-0000-0000-0000-000000000013', 'B', 'Start high-dose corticosteroids immediately without stopping the omeprazole or considering biopsy', false, 'Ruled out because the essential first step is to remove the causative agent; corticosteroids may be considered in AIN if renal function fails to improve after drug withdrawal, but the causative drug should not be continued.', 2),
('dd000000-0000-0000-0000-000000000013', 'C', 'Arrange renal angiography to exclude renal artery stenosis', false, 'Ruled out because the clinical and laboratory picture (fever, eosinophilia, pyuria, temporal relationship with a known culprit drug) is not suggestive of renovascular disease, and angiography is not indicated here.', 3),
('dd000000-0000-0000-0000-000000000013', 'D', 'Increase the omeprazole dose to rule out a dose-independent cause', false, 'Ruled out because this is nonsensical management; the appropriate action is to stop the suspected causative drug, not increase its dose.', 4),
('dd000000-0000-0000-0000-000000000013', 'E', 'Stop the omeprazole and consider renal biopsy if renal function does not improve', true, 'Correct. The clinical picture (subacute AKI, low-grade fever, eosinophilia, sterile pyuria, normal imaging) in a patient on a proton pump inhibitor is classic for drug-induced acute interstitial nephritis. The first step is withdrawal of the likely offending drug; if renal function does not recover or the diagnosis remains uncertain, renal biopsy can confirm the diagnosis and guide consideration of corticosteroid therapy.', 5),
('dd000000-0000-0000-0000-000000000014', 'A', 'Continue gentamicin at the same dose since trough levels have been therapeutic', false, 'Ruled out because therapeutic trough levels do not preclude aminoglycoside nephrotoxicity, which results from cumulative drug accumulation in proximal tubular cells irrespective of a single trough measurement; continuing at the same dose risks further renal injury.', 1),
('dd000000-0000-0000-0000-000000000014', 'B', 'Increase the gentamicin dose to ensure adequate endocarditis treatment despite renal impairment', false, 'Ruled out because increasing the dose of a likely nephrotoxic agent in the context of worsening renal function would worsen kidney injury and is inappropriate; dose adjustment or discontinuation is needed.', 2),
('dd000000-0000-0000-0000-000000000014', 'C', 'Start haemodialysis immediately as the primary treatment for aminoglycoside toxicity', false, 'Ruled out because aminoglycoside-induced ATN is generally managed supportively with drug cessation/adjustment; dialysis is reserved for standard AKI indications (severe electrolyte disturbance, fluid overload, uraemic complications), not routinely for aminoglycoside nephrotoxicity itself.', 3),
('dd000000-0000-0000-0000-000000000014', 'D', 'Stop or substitute the gentamicin, switch to extended-interval dosing with closer level monitoring if aminoglycoside therapy must continue, and support renal function', true, 'Correct. This presentation (non-oliguric AKI with granular casts after a course of an aminoglycoside) is typical of aminoglycoside-induced acute tubular necrosis, which can occur even with therapeutic trough levels due to cumulative proximal tubular accumulation. Management involves stopping or minimising aminoglycoside exposure, using alternative agents where possible, and if continued therapy is essential, using extended-interval dosing with vigilant level monitoring, alongside general supportive AKI management.', 4),
('dd000000-0000-0000-0000-000000000014', 'E', 'Add an NSAID for symptomatic control, as it will not affect renal recovery', false, 'Ruled out because NSAIDs cause additional nephrotoxicity via reduced renal prostaglandin-mediated perfusion and would compound the existing tubular injury; they should be avoided in AKI.', 5),
('dd000000-0000-0000-0000-000000000015', 'A', 'Continue the NSAID at a reduced dose and monitor renal function closely', false, 'Ruled out because continuing any dose of the causative NSAID would perpetuate both the interstitial nephritis and the nephrotic syndrome; the drug must be stopped.', 1),
('dd000000-0000-0000-0000-000000000015', 'B', 'Start cyclophosphamide immediately as first-line therapy without a trial of drug withdrawal', false, 'Ruled out because drug withdrawal (and corticosteroids if needed) is the appropriate initial approach; cyclophosphamide is not first-line for NSAID-associated minimal change disease and would expose the patient to unnecessary toxicity.', 2),
('dd000000-0000-0000-0000-000000000015', 'C', 'Stop the NSAID and give a course of corticosteroids if proteinuria and renal function do not improve with withdrawal alone', true, 'Correct. NSAIDs can cause both acute interstitial nephritis and, less commonly, a NSAID-associated minimal change-like nephrotic syndrome via a T-cell-mediated mechanism, sometimes coexisting as in this biopsy. The first step is stopping the NSAID; if nephrotic syndrome and renal impairment do not resolve with drug withdrawal, a corticosteroid course is used, as for other causes of minimal change disease.', 3),
('dd000000-0000-0000-0000-000000000015', 'D', 'Reassure the patient that this will resolve spontaneously with no specific intervention needed', false, 'Ruled out because although withdrawal of the NSAID is essential and can lead to improvement, active monitoring and consideration of corticosteroids if the nephrotic syndrome and renal impairment persist is appropriate rather than pure watchful waiting with no intervention.', 4),
('dd000000-0000-0000-0000-000000000015', 'E', 'Switch to a COX-2 selective inhibitor to reduce gastrointestinal side effects while continuing anti-inflammatory therapy', false, 'Ruled out because COX-2 selective inhibitors carry similar nephrotoxic potential (including interstitial nephritis and nephrotic syndrome) to non-selective NSAIDs and should also be avoided in this context.', 5),
('dd000000-0000-0000-0000-000000000016', 'A', 'Consider switching to an alternative mood stabiliser in conjunction with psychiatry, and if lithium must continue, add amiloride to reduce nephrogenic diabetes insipidus symptoms', true, 'Correct. Chronic lithium therapy causes nephrogenic diabetes insipidus by downregulating aquaporin-2 channels in the collecting duct, producing polyuria unresponsive to desmopressin. Management involves a joint discussion with psychiatry about whether lithium can be stopped or reduced; if it must continue for psychiatric stability, amiloride can be added because it blocks lithium entry into collecting duct cells via the epithelial sodium channel, reducing nephrogenic diabetes insipidus severity while allowing continued lithium use.', 1),
('dd000000-0000-0000-0000-000000000016', 'B', 'Increase the lithium dose since the current level is within the therapeutic range and this cannot be the cause', false, 'Ruled out because a therapeutic lithium level does not exclude lithium-induced nephrogenic diabetes insipidus, which results from cumulative long-term tubular effects rather than acute toxicity; increasing the dose would worsen the underlying problem and risk acute toxicity.', 2),
('dd000000-0000-0000-0000-000000000016', 'C', 'Start desmopressin as the definitive treatment for this diabetes insipidus', false, 'Ruled out because the water deprivation test already showed no response to desmopressin, confirming a nephrogenic (not central) mechanism; desmopressin would not be effective here.', 3),
('dd000000-0000-0000-0000-000000000016', 'D', 'Stop lithium abruptly without psychiatric input given the renal findings', false, 'Ruled out because abrupt cessation of lithium without psychiatric input risks precipitating a mood relapse; any change to a mood-stabilising regimen for chronic psychiatric illness should be made collaboratively with psychiatry.', 4),
('dd000000-0000-0000-0000-000000000016', 'E', 'Restrict fluid intake strictly to control the polyuria', false, 'Ruled out because in nephrogenic diabetes insipidus the kidneys cannot concentrate urine, so fluid restriction risks dangerous hypernatraemia and dehydration rather than controlling the underlying problem.', 5),
('dd000000-0000-0000-0000-000000000017', 'A', 'Continue tenofovir at the same dose and treat only the electrolyte abnormalities symptomatically', false, 'Ruled out because continuing the causative drug would allow ongoing proximal tubular injury and progressive renal impairment; the underlying cause should be addressed by switching therapy, not just treating downstream electrolyte derangements.', 1),
('dd000000-0000-0000-0000-000000000017', 'B', 'Increase the tenofovir dose to improve virological control given ongoing tubulopathy', false, 'Ruled out because increasing the dose of a drug causing proximal tubular toxicity would worsen the Fanconi syndrome and renal impairment.', 2),
('dd000000-0000-0000-0000-000000000017', 'C', 'Switch to an alternative antiretroviral agent with lower renal tubular toxicity, in conjunction with HIV specialists', true, $x$Correct. This presentation (glycosuria with normal glucose, phosphaturia causing hypophosphataemia, hypokalaemia, low-molecular-weight proteinuria, and normal-anion-gap acidosis) is classic for tenofovir disoproxil fumarate-induced proximal renal tubulopathy (Fanconi syndrome), caused by mitochondrial toxicity to proximal tubular cells. Management involves switching to a renally safer alternative (such as tenofovir alafenamide or another agent) in conjunction with the patient's HIV specialist team, alongside correcting electrolyte abnormalities.$x$, 3),
('dd000000-0000-0000-0000-000000000017', 'D', 'Arrange renal biopsy as the essential next step before any medication change', false, 'Ruled out because the clinical and biochemical picture is sufficiently characteristic of tenofovir-induced proximal tubulopathy that a trial of drug substitution is appropriate first; biopsy is not required before acting on this recognised drug-induced syndrome.', 4),
('dd000000-0000-0000-0000-000000000017', 'E', 'Start high-dose corticosteroids for presumed autoimmune tubulointerstitial nephritis', false, 'Ruled out because there is no indication this is autoimmune; the clinical and laboratory findings point specifically to tenofovir-related mitochondrial proximal tubular toxicity, which is managed by drug withdrawal/substitution, not immunosuppression.', 5),
('dd000000-0000-0000-0000-000000000018', 'A', 'Contrast-induced nephropathy; give intravenous fluids and expect renal recovery within 48-72 hours', false, 'Ruled out because contrast-induced nephropathy typically manifests within 24-48 hours post-procedure and resolves within days to weeks without the systemic features (livedo reticularis, digital ischaemia, eosinophilia, hypocomplementaemia) described here, which specifically indicate atheroembolism.', 1),
('dd000000-0000-0000-0000-000000000018', 'B', 'ANCA-associated vasculitis; start high-dose corticosteroids and cyclophosphamide immediately', false, 'Ruled out because although vasculitis can cause similar cutaneous and renal features, the clear temporal relationship to arterial catheterisation and the characteristic combination of findings make cholesterol embolisation the much more likely diagnosis; ANCA serology would help differentiate before committing to aggressive immunosuppression.', 2),
('dd000000-0000-0000-0000-000000000018', 'C', 'Heparin-induced thrombocytopenia with thrombosis; stop heparin and start a direct thrombin inhibitor', false, 'Ruled out because there is no mention of thrombocytopenia or heparin exposure driving a hypercoagulable state consistent with HIT, and the described features fit atheroembolic disease from the recent arterial procedure far better.', 3),
('dd000000-0000-0000-0000-000000000018', 'D', 'Cholesterol (atheroembolic) embolisation syndrome; manage supportively, optimise cardiovascular risk factors, and avoid further vascular instrumentation and anticoagulation where possible', true, 'Correct. The combination of livedo reticularis, digital ischaemia, eosinophilia, subacute renal impairment, and mild hypocomplementaemia occurring days to weeks after an arterial procedure is characteristic of cholesterol embolisation syndrome from dislodged atheromatous plaque. Management is largely supportive (blood pressure and risk factor control, avoiding further arterial instrumentation and, where possible, anticoagulation which can promote further plaque disruption); there is no specific reversal therapy, and renal function may only partially recover.', 4),
('dd000000-0000-0000-0000-000000000018', 'E', 'Acute interstitial nephritis secondary to contrast dye; start corticosteroids', false, 'Ruled out because contrast is not typically associated with an AIN-type reaction, and the systemic embolic features (livedo, digital ischaemia, hypocomplementaemia) are not explained by AIN; the picture is characteristic of atheroembolism, not a hypersensitivity interstitial reaction.', 5),
('dd000000-0000-0000-0000-000000000019', 'A', 'Restrict fluids to 1 litre per day as for SIADH', false, 'Ruled out because this patient is hypovolaemic (postural drop, high urine output with natriuresis), not euvolaemic/hypervolaemic as in SIADH; fluid restriction in cerebral salt wasting would worsen hypovolaemia and risk cerebral vasospasm-related ischaemia, which is particularly dangerous after subarachnoid haemorrhage.', 1),
('dd000000-0000-0000-0000-000000000019', 'B', 'Start a vasopressin V2-receptor antagonist (vaptan) to correct the hyponatraemia', false, 'Ruled out because vaptans are used for euvolaemic or hypervolaemic hyponatraemia (e.g. SIADH), not for the hypovolaemic hyponatraemia of cerebral salt wasting, where they would further deplete intravascular volume.', 2),
('dd000000-0000-0000-0000-000000000019', 'C', 'Give desmopressin to reduce urine output and slow sodium loss', false, 'Ruled out because desmopressin would promote water retention and could worsen hyponatraemia; the underlying issue in cerebral salt wasting is renal sodium loss, which needs replacement, not antidiuresis.', 3),
('dd000000-0000-0000-0000-000000000019', 'D', 'Withhold all sodium-containing fluids and monitor sodium daily without active correction', false, 'Ruled out because this hypovolaemic, natriuretic hyponatraemia requires active volume and sodium repletion; withholding sodium would allow ongoing volume depletion and risk cerebral ischaemia in the critical post-subarachnoid haemorrhage period, when maintaining cerebral perfusion is paramount.', 4),
('dd000000-0000-0000-0000-000000000019', 'E', 'Correct with isotonic saline and salt replacement, aiming to restore intravascular volume', true, 'Correct. The clinical picture of hypovolaemia with high urinary sodium losses following subarachnoid haemorrhage is characteristic of cerebral salt wasting rather than SIADH; unlike SIADH, cerebral salt wasting is a hypovolaemic hyponatraemia caused by renal sodium and volume loss (thought to relate to natriuretic peptide release), so treatment requires volume and sodium replacement with isotonic (or hypertonic if severe/symptomatic) saline, not fluid restriction.', 5),
('dd000000-0000-0000-0000-000000000020', 'A', 'Restrict fluids alone, since psychogenic polydipsia is a purely water-excess problem that will resolve without hypertonic saline', false, 'Ruled out because fluid restriction alone is too slow for a patient with active seizures from severe symptomatic hyponatraemia; the emergency requires prompt hypertonic saline to raise sodium quickly enough to stop ongoing neurological injury.', 1),
('dd000000-0000-0000-0000-000000000020', 'B', 'Give a bolus of hypertonic (3%) saline to acutely raise sodium by a small increment, then closely monitor sodium every 2-4 hours to avoid correcting by more than 8-10 mmol/L in the first 24 hours', true, 'Correct. Severe symptomatic hyponatraemia with seizures is a medical emergency requiring prompt but carefully limited correction with hypertonic saline (typically 100-150 mL boluses of 3% saline, repeated if symptoms persist) to acutely reduce cerebral oedema risk. However, overly rapid correction (generally more than 8-10 mmol/L in 24 hours, less in chronic or malnourished/alcoholic patients) risks osmotic demyelination syndrome, so frequent monitoring and, if correction is running ahead of target, deliberate re-lowering (e.g. with desmopressin and/or dextrose water) may be needed.', 2),
('dd000000-0000-0000-0000-000000000020', 'C', 'Correct the sodium rapidly and fully to normal range within the first few hours to stop further seizures', false, 'Ruled out because rapid, large-magnitude correction of sodium (beyond the recommended 8-10 mmol/L/24h limit) markedly increases the risk of osmotic demyelination syndrome, which can cause severe, sometimes irreversible neurological injury.', 3),
('dd000000-0000-0000-0000-000000000020', 'D', 'Give large volumes of 0.9% normal saline as the definitive treatment', false, 'Ruled out because normal saline is not the preferred emergency treatment for severe symptomatic hyponatraemia (hypertonic saline is required to acutely raise sodium sufficiently), and in psychogenic polydipsia even isotonic saline can sometimes be retained as free water depending on urine osmolality, risking further dilution.', 4),
('dd000000-0000-0000-0000-000000000020', 'E', 'Give oral salt tablets only, without any intravenous treatment, given the seizure has already terminated', false, 'Ruled out because ongoing severe symptomatic hyponatraemia with seizure history requires prompt intravenous hypertonic saline; oral salt alone acts too slowly for this emergency.', 5),
('dd000000-0000-0000-0000-000000000021', 'A', 'Stop the ACE inhibitor immediately as the first-line action', false, 'Ruled out because ACE inhibitors confer important cardiovascular and renal protective benefits, and current practice favours using potassium-lowering strategies (dietary measures, potassium binders) to permit continuation of RAAS blockade rather than reflexively stopping it for moderate, asymptomatic hyperkalaemia.', 1),
('dd000000-0000-0000-0000-000000000021', 'B', 'Start calcium resonium for long-term maintenance therapy', false, 'Ruled out because calcium resonium is poorly tolerated for long-term use (gastrointestinal side effects, risk of intestinal necrosis) and has largely been superseded by patiromer and sodium zirconium cyclosilicate for chronic outpatient management.', 2),
('dd000000-0000-0000-0000-000000000021', 'C', 'Arrange urgent haemodialysis for potassium removal', false, 'Ruled out because this is asymptomatic, non-emergency hyperkalaemia with a normal ECG; dialysis is not indicated for chronic outpatient management at this level.', 3),
('dd000000-0000-0000-0000-000000000021', 'D', 'Start a novel potassium binder such as patiromer or sodium zirconium cyclosilicate to allow continuation of the ACE inhibitor', true, 'Correct. In chronic, moderate hyperkalaemia in a patient benefiting from RAAS blockade for cardiorenal protection, novel potassium binders (patiromer, sodium zirconium cyclosilicate) allow ongoing potassium control while permitting continuation of the ACE inhibitor, rather than withdrawing a drug with important long-term cardiovascular and renal benefits.', 4),
('dd000000-0000-0000-0000-000000000021', 'E', 'Add a potassium-sparing diuretic to further optimise blood pressure control', false, 'Ruled out because a potassium-sparing diuretic would exacerbate hyperkalaemia and is contraindicated in this context.', 5),
('dd000000-0000-0000-0000-000000000022', 'A', 'Central diabetes insipidus; start desmopressin with regular sodium monitoring', true, 'Correct. A marked response to exogenous desmopressin (concentration of urine, reduction in output) after previously dilute urine and hypernatraemia confirms a central (vasopressin-deficient) rather than nephrogenic cause, consistent with post-surgical damage to the posterior pituitary/hypothalamic axis. Desmopressin replacement is the appropriate treatment, with regular monitoring for the risk of hyponatraemia from overtreatment or evolving into a triphasic response.', 1),
('dd000000-0000-0000-0000-000000000022', 'B', 'Nephrogenic diabetes insipidus; manage with thiazide diuretics and dietary salt/protein restriction', false, 'Ruled out because the marked response to desmopressin excludes a nephrogenic cause (in which the kidney is unresponsive to vasopressin); this patient has a central deficiency, appropriately managed with desmopressin replacement rather than the nephrogenic DI strategy.', 2),
('dd000000-0000-0000-0000-000000000022', 'C', 'SIADH; restrict fluids to 1 litre per day', false, $x$Ruled out because SIADH causes euvolaemic hyponatraemia with concentrated urine due to excess ADH, the opposite biochemical pattern to this patient's hypernatraemia with dilute urine that concentrates in response to desmopressin.$x$, 3),
('dd000000-0000-0000-0000-000000000022', 'D', 'Cerebral salt wasting; give hypertonic saline and salt supplementation', false, 'Ruled out because cerebral salt wasting causes hyponatraemia with volume depletion and natriuresis, not hypernatraemia with polyuria that responds to desmopressin as seen here.', 4),
('dd000000-0000-0000-0000-000000000022', 'E', 'Primary polydipsia; restrict fluid intake without hormone replacement', false, 'Ruled out because primary polydipsia is a diagnosis of excessive fluid intake causing dilutional hyponatraemia typically, not hypernatraemia, and would not show this desmopressin-responsive concentrating defect.', 5),
('dd000000-0000-0000-0000-000000000023', 'A', 'Start a loop diuretic immediately as the primary treatment before any fluid resuscitation', false, 'Ruled out because loop diuretics should not be used as primary treatment for hypercalcaemia and should never be given before adequate volume repletion, as this would worsen volume depletion and further impair renal calcium excretion.', 1),
('dd000000-0000-0000-0000-000000000023', 'B', 'Give intravenous isotonic saline for rehydration, followed by an intravenous bisphosphonate once adequately hydrated', true, 'Correct. Severe hypercalcaemia of malignancy is managed initially with intravenous isotonic saline to correct volume depletion (which itself worsens hypercalcaemia by reducing renal calcium clearance), followed by an intravenous bisphosphonate (e.g. zoledronic acid, with dose adjustment or alternative such as denosumab considered if renal function is significantly impaired) to inhibit osteoclast-mediated bone resorption, which takes 2-4 days to achieve maximal effect.', 2),
('dd000000-0000-0000-0000-000000000023', 'C', 'Give oral bisphosphonate therapy as the first-line treatment for this severity of hypercalcaemia', false, 'Ruled out because oral bisphosphonates have poor bioavailability and are not appropriate for acute, severe hypercalcaemia; intravenous bisphosphonate therapy is required.', 3),
('dd000000-0000-0000-0000-000000000023', 'D', 'Restrict all fluids to reduce calcium delivery to the kidney', false, 'Ruled out because fluid restriction would worsen volume depletion and further reduce renal calcium excretion, exacerbating hypercalcaemia; rehydration is required first.', 4),
('dd000000-0000-0000-0000-000000000023', 'E', 'Proceed directly to haemodialysis without a trial of fluids and bisphosphonate', false, 'Ruled out because dialysis is reserved for severe, symptomatic hypercalcaemia refractory to standard therapy or when renal function precludes safe bisphosphonate use; first-line treatment here is fluids followed by bisphosphonate.', 5),
('dd000000-0000-0000-0000-000000000024', 'A', 'Refeeding syndrome; increase the feeding rate to provide more calories and correct the underlying malnutrition faster', false, 'Ruled out because increasing feeding rate would worsen the insulin-driven intracellular electrolyte shifts causing refeeding syndrome; the correct approach is to slow feeding while aggressively replacing electrolytes.', 1),
('dd000000-0000-0000-0000-000000000024', 'B', 'Diabetic ketoacidosis; start an insulin infusion and intravenous fluids per DKA protocol', false, 'Ruled out because there is no mention of hyperglycaemia, ketosis, or acidosis; the clinical context (starvation followed by refeeding) and the pattern of combined hypophosphataemia, hypokalaemia, and hypomagnesaemia are characteristic of refeeding syndrome, not DKA.', 2),
('dd000000-0000-0000-0000-000000000024', 'C', 'Refeeding syndrome; slow or temporarily reduce the rate of feeding and aggressively replace phosphate, potassium, and magnesium', true, $x$Correct. This is refeeding syndrome, occurring when carbohydrate reintroduction after prolonged starvation triggers an insulin surge that drives potassium, phosphate, and magnesium intracellularly, causing profound extracellular depletion of all three. Management involves slowing or temporarily reducing feeding rate and urgent, aggressive replacement of phosphate, potassium, and magnesium, alongside thiamine supplementation to prevent Wernicke's encephalopathy, with cardiac monitoring given arrhythmia risk from these severe electrolyte disturbances.$x$, 3),
('dd000000-0000-0000-0000-000000000024', 'D', 'Rhabdomyolysis; give aggressive intravenous fluid resuscitation as the priority', false, 'Ruled out because there is no creatine kinase elevation or myoglobinuria described, and the electrolyte pattern combined with the clinical context of recent refeeding after starvation is specific for refeeding syndrome rather than rhabdomyolysis.', 4),
('dd000000-0000-0000-0000-000000000024', 'E', 'Primary hyperparathyroidism; arrange urgent parathyroidectomy', false, 'Ruled out because primary hyperparathyroidism causes hypercalcaemia with typically low phosphate but would not explain this combination of severe hypokalaemia and hypomagnesaemia in the setting of recent refeeding, and there is no calcium abnormality described; urgent parathyroidectomy is not indicated acutely regardless.', 5),
('dd000000-0000-0000-0000-000000000025', 'A', 'Tolvaptan, with no specific monitoring required beyond routine renal function tests', false, 'Ruled out because tolvaptan carries a specific, well-documented risk of hepatotoxicity requiring dedicated, frequent liver function monitoring, particularly during the initial period of treatment; routine renal function tests alone are insufficient.', 1),
('dd000000-0000-0000-0000-000000000025', 'B', 'Somatostatin analogue therapy as first-line disease-modifying treatment for ADPKD', false, 'Ruled out because somatostatin analogues have shown benefit mainly for hepatic cyst burden and are not the first-line disease-modifying therapy for ADPKD renal progression; tolvaptan has the strongest evidence and licensing for slowing renal cyst growth and function decline.', 2),
('dd000000-0000-0000-0000-000000000025', 'C', 'ACE inhibitor dose escalation alone as the only necessary additional intervention', false, 'Ruled out because blood pressure is already well controlled, and ACE inhibitors, while important for blood pressure and cardiovascular risk management in ADPKD, have not been shown to specifically slow cyst growth or eGFR decline in the way tolvaptan has in appropriately selected rapidly progressive disease.', 3),
('dd000000-0000-0000-0000-000000000025', 'D', 'Immediate referral for bilateral native nephrectomy to reduce total kidney volume', false, 'Ruled out because nephrectomy is not indicated for disease modification at this stage and is reserved for specific complications (e.g. severe pain, recurrent infected cysts, or to create space pre-transplant), not as a routine intervention for progressive ADPKD.', 4),
('dd000000-0000-0000-0000-000000000025', 'E', 'Tolvaptan, with regular monitoring of liver function tests, particularly in the first 18 months of treatment', true, 'Correct. Tolvaptan, a vasopressin V2-receptor antagonist, is licensed to slow cyst growth and eGFR decline in ADPKD patients with evidence of rapidly progressive disease. It carries a risk of idiosyncratic, potentially severe hepatotoxicity, so regular liver function monitoring (typically monthly for the first 18 months, then periodically thereafter) is mandatory, alongside monitoring for aquaresis-related effects such as polyuria and hypernatraemia.', 5),
('dd000000-0000-0000-0000-000000000026', 'A', 'No screening is required, as intracranial aneurysm screening is never indicated in ADPKD', false, 'Ruled out because although universal screening is not recommended, screening is specifically indicated in ADPKD patients with a family history of intracranial aneurysm or subarachnoid haemorrhage, which this patient has.', 1),
('dd000000-0000-0000-0000-000000000026', 'B', 'Screen only if he develops a severe headache, as this is the only indication for imaging', false, 'Ruled out because a sudden severe headache would suggest an already-ruptured aneurysm requiring emergency imaging, not the pre-emptive screening that is indicated based on his family history in the absence of symptoms.', 2),
('dd000000-0000-0000-0000-000000000026', 'C', 'Perform genetic testing for the specific familial PKD mutation before considering any imaging', false, 'Ruled out because the immediate relevant action given the family history of aneurysm/subarachnoid haemorrhage is vascular imaging (MR angiography), not genetic mutation characterisation, which would not change the indication for aneurysm screening.', 3),
('dd000000-0000-0000-0000-000000000026', 'D', 'Refer directly for CT angiography with iodinated contrast as the preferred first-line screening modality', false, 'Ruled out because MR angiography (without the need for iodinated contrast or ionising radiation) is the preferred non-invasive screening modality for intracranial aneurysms in ADPKD, particularly relevant given the potential for future contrast exposure and renal impairment.', 4),
('dd000000-0000-0000-0000-000000000026', 'E', 'Arrange MR angiography of the brain given his significant family history of intracranial aneurysm/subarachnoid haemorrhage', true, $x$Correct. Routine screening for intracranial aneurysms is not recommended for all ADPKD patients, but is indicated for those with a family history of intracranial aneurysm or subarachnoid haemorrhage, high-risk occupations, or prior to major elective surgery with anticipated haemodynamic instability. This patient's strong family history (a first-degree relative who died of subarachnoid haemorrhage and another affected first-degree relative) is a clear indication for MR angiography screening.$x$, 5),
('dd000000-0000-0000-0000-000000000027', 'A', $x$Anti-GBM (Goodpasture's) disease in the transplanted kidney, because his native kidneys lack a normal alpha-5(IV) collagen antigen that the transplanted kidney (with normal collagen) newly exposes to his immune system$x$, true, $x$Correct. Alport syndrome (X-linked, COL4A5 mutation in this pedigree pattern) results in abnormal type IV collagen in the glomerular basement membrane, associated with sensorineural deafness and lenticonus. Because his immune system has never been exposed to the normal alpha-5(IV) collagen chain, a transplanted kidney expressing normal collagen can act as a 'foreign' antigen, triggering anti-GBM antibody formation and a Goodpasture's-like presentation, a recognised though uncommon complication specific to Alport transplant recipients.$x$, 1),
('dd000000-0000-0000-0000-000000000027', 'B', 'Recurrent FSGS in the transplanted kidney due to a circulating permeability factor', false, 'Ruled out because recurrent FSGS with a circulating permeability factor is a well-recognised risk specifically for primary FSGS transplant recipients, not the mechanism of concern in Alport syndrome, which instead relates to alloimmune anti-GBM antibody formation against normal collagen.', 2),
('dd000000-0000-0000-0000-000000000027', 'C', 'Recurrence of IgA nephropathy in the graft', false, $x$Ruled out because this patient's presentation (deafness, lenticonus, characteristic basement membrane splitting on electron microscopy, X-linked pattern) is diagnostic of Alport syndrome, not IgA nephropathy, and the specific transplant risk relevant to Alport syndrome is anti-GBM disease, not IgA recurrence.$x$, 3),
('dd000000-0000-0000-0000-000000000027', 'D', 'BK virus-associated nephropathy due to an underlying immune deficiency', false, 'Ruled out because Alport syndrome is not an immunodeficiency state, and there is no particular association between Alport syndrome and increased BK virus risk beyond that of any transplant recipient on standard immunosuppression.', 4),
('dd000000-0000-0000-0000-000000000027', 'E', 'Recurrent membranous nephropathy from anti-PLA2R antibodies', false, $x$Ruled out because this patient's biopsy findings and clinical syndrome are diagnostic of Alport syndrome, not membranous nephropathy, and PLA2R antibody recurrence is not the relevant post-transplant risk here.$x$, 5),
('dd000000-0000-0000-0000-000000000028', 'A', 'Renal biopsy alone is diagnostic and no specific systemic treatment is available or needed', false, 'Ruled out because effective disease-specific enzyme replacement therapy exists for Fabry disease and should be offered, alongside renoprotective measures, rather than providing no treatment.', 1),
('dd000000-0000-0000-0000-000000000028', 'B', 'High-dose corticosteroids as first-line therapy for the renal manifestations', false, 'Ruled out because Fabry nephropathy results from lysosomal glycolipid accumulation, not an immune-mediated glomerulonephritis, so corticosteroids have no specific role; enzyme replacement therapy is the disease-specific treatment.', 2),
('dd000000-0000-0000-0000-000000000028', 'C', 'Enzyme replacement therapy with recombinant alpha-galactosidase A, alongside RAAS blockade for proteinuria', true, $x$Correct. This clinical and biopsy picture (acroparaesthesias, angiokeratomas, corneal verticillata, podocyte lipid inclusions/'zebra bodies') confirms Fabry disease, an X-linked lysosomal storage disorder from alpha-galactosidase A deficiency causing globotriaosylceramide accumulation. Disease-specific management is enzyme replacement therapy (agalsidase alfa or beta, or oral chaperone therapy migalastat in amenable mutations), alongside standard renoprotective measures such as RAAS blockade for proteinuria, to slow progression of Fabry nephropathy.$x$, 3),
('dd000000-0000-0000-0000-000000000028', 'D', 'Plasma exchange to remove circulating globotriaosylceramide', false, 'Ruled out because plasma exchange is not an established or effective treatment for Fabry disease; enzyme replacement therapy is the standard of care to address the underlying enzyme deficiency.', 4),
('dd000000-0000-0000-0000-000000000028', 'E', 'Genetic counselling only, with no pharmacological treatment until end-stage renal disease develops', false, $x$Ruled out because enzyme replacement therapy is indicated once there is evidence of organ involvement (such as this patient's proteinuria and biopsy-proven Fabry nephropathy) rather than waiting until end-stage renal failure develops, since earlier treatment aims to slow progression of organ damage.$x$, 5),
('dd000000-0000-0000-0000-000000000029', 'A', 'Autosomal dominant polycystic kidney disease with an atypical presentation', false, 'Ruled out because ADPKD is characterised by progressive, marked renal cyst formation and enlargement on imaging, which is explicitly absent here (normal-sized kidneys without significant cysts), and the causative gene identified (UMOD) is not a PKD gene.', 1),
('dd000000-0000-0000-0000-000000000029', 'B', 'Autosomal recessive polycystic kidney disease presenting later than usual', false, 'Ruled out because the family history spans multiple generations affected in a pattern consistent with autosomal dominant inheritance, not autosomal recessive, and again there is no significant cystic change on imaging.', 2),
('dd000000-0000-0000-0000-000000000029', 'C', 'Medullary sponge kidney with secondary gout from recurrent stone disease', false, 'Ruled out because medullary sponge kidney is typically a sporadic condition associated with nephrocalcinosis and stone disease on imaging, not an inherited progressive CKD with early hyperuricaemia driven by a UMOD mutation.', 3),
('dd000000-0000-0000-0000-000000000029', 'D', 'Autosomal dominant tubulointerstitial kidney disease (UMOD-related); unlike ADPKD, kidneys are typically normal or small in size without significant cystic change, and early-onset gout/hyperuricaemia is a prominent, distinguishing feature', true, 'Correct. UMOD-related autosomal dominant tubulointerstitial kidney disease (previously termed familial juvenile hyperuricaemic nephropathy) causes slowly progressive CKD with a hallmark of disproportionately early-onset hyperuricaemia and gout relative to the degree of renal impairment, inherited in an autosomal dominant pattern. Unlike ADPKD, imaging shows normal or small kidneys without significant cyst burden, helping distinguish it from ADPKD despite the similar autosomal dominant inheritance and family history of progressive renal failure.', 4),
('dd000000-0000-0000-0000-000000000029', 'E', 'Lesch-Nyhan syndrome causing renal impairment secondary to urate nephropathy', false, 'Ruled out because Lesch-Nyhan syndrome is an X-linked recessive disorder of purine metabolism presenting in male infants with severe neurological and behavioural features, entirely inconsistent with this adult-onset, autosomal dominant, UMOD-associated family pattern.', 5),
('dd000000-0000-0000-0000-000000000030', 'A', 'Observation with repeat imaging in 12 months, as intervention is only indicated once symptoms develop', false, 'Ruled out because a large angiomyolipoma (>3-4 cm) with an enlarging internal aneurysm carries a significant risk of life-threatening spontaneous haemorrhage even before symptoms occur, so pre-emptive intervention (rather than watchful waiting alone) is indicated at this size and with this aneurysmal feature.', 1),
('dd000000-0000-0000-0000-000000000030', 'B', 'Selective renal artery embolisation to reduce haemorrhage risk, with consideration of an mTOR inhibitor (e.g. everolimus) for durable long-term lesion control', true, 'Correct. Angiomyolipomas larger than 3-4 cm, and particularly those with an associated aneurysm, carry a significant risk of spontaneous, potentially life-threatening haemorrhage (Wunderlich syndrome), so pre-emptive intervention is indicated even in asymptomatic patients. Selective embolisation is used to address the acute bleeding risk, while an mTOR inhibitor (targeting the underlying TSC1/TSC2-mTOR pathway dysregulation) offers durable reduction in angiomyolipoma size and is often used for longer-term control, particularly with multiple or bilateral lesions as is typical in tuberous sclerosis.', 2),
('dd000000-0000-0000-0000-000000000030', 'C', 'Immediate radical nephrectomy as the definitive treatment', false, 'Ruled out because nephron-sparing approaches (embolisation, partial nephrectomy if needed, mTOR inhibitors) are preferred in tuberous sclerosis given the tendency for multiple and bilateral lesions, and radical nephrectomy would unnecessarily sacrifice functioning renal tissue when less destructive options control the haemorrhage risk effectively.', 3),
('dd000000-0000-0000-0000-000000000030', 'D', 'Start high-dose corticosteroids to reduce the size of the angiomyolipoma', false, 'Ruled out because angiomyolipomas are benign mesenchymal tumours related to mTOR pathway dysregulation, not an inflammatory process, so corticosteroids have no role in their management.', 4),
('dd000000-0000-0000-0000-000000000030', 'E', 'Reassure the patient that angiomyolipomas in tuberous sclerosis never require intervention', false, $x$Ruled out because although many angiomyolipomas are managed conservatively, this lesion's size and aneurysmal change place the patient at significant haemorrhage risk, specifically warranting pre-emptive intervention.$x$, 5),
('dd000000-0000-0000-0000-000000000031', 'A', 'Continue conservative management alone for a further 12 months before considering immunosuppression', false, 'Ruled out because this patient already shows declining eGFR alongside persistent severe nephrotic syndrome despite 6 months of maximised conservative therapy, meeting recognised criteria to escalate to immunosuppressive treatment rather than prolonging observation, which risks further irreversible renal injury.', 1),
('dd000000-0000-0000-0000-000000000031', 'B', 'Start high-dose corticosteroid monotherapy as the preferred first-line immunosuppressive regimen', false, 'Ruled out because corticosteroid monotherapy has not been shown to be effective in idiopathic membranous nephropathy, and current evidence-based regimens use either cyclical corticosteroid/alkylating agent therapy or rituximab (or calcineurin inhibitors), not steroids alone.', 2),
('dd000000-0000-0000-0000-000000000031', 'C', 'Proceed to renal transplant work-up given declining eGFR', false, 'Ruled out because eGFR of 68 is not end-stage and this is a potentially treatable immune-mediated glomerulonephritis; immunosuppressive treatment aimed at inducing remission is indicated well before transplant work-up would be considered.', 3),
('dd000000-0000-0000-0000-000000000031', 'D', 'Perform a repeat renal biopsy before considering any change in management', false, 'Ruled out because the diagnosis is already confirmed with biopsy and a strongly positive anti-PLA2R titre; a repeat biopsy is not required to justify escalating to immunosuppressive therapy given the clear clinical trajectory (persistent nephrotic syndrome, declining eGFR despite conservative therapy).', 4),
('dd000000-0000-0000-0000-000000000031', 'E', 'Start immunosuppressive therapy with rituximab', true, 'Correct. Persistent nephrotic-range proteinuria with declining renal function despite maximised conservative (RAAS blockade, salt restriction) therapy in PLA2R-associated membranous nephropathy meets criteria for immunosuppressive treatment. Rituximab is now a preferred first-line immunosuppressive option in many guidelines given its efficacy and more favourable toxicity profile compared with cyclophosphamide-based regimens, particularly for moderate-risk disease, and anti-PLA2R titre can also be used to monitor immunological response.', 5),
('dd000000-0000-0000-0000-000000000032', 'A', $x$A targeted-release formulation of budesonide (acting locally on Peyer's patches in the ileum) to reduce mucosal-derived pathogenic IgA production$x$, true, 'Correct. In IgA nephropathy with persistent proteinuria despite optimised supportive therapy (maximised RAAS blockade plus SGLT2 inhibition), and without features suggesting a rapidly progressive crescentic course requiring systemic immunosuppression, targeted-release budesonide (designed to act locally on gut-associated lymphoid tissue implicated in generating pathogenic galactose-deficient IgA1) is a licensed, evidence-based option shown to reduce proteinuria and slow eGFR decline, with a more favourable systemic side-effect profile than conventional systemic corticosteroids.', 1),
('dd000000-0000-0000-0000-000000000032', 'B', 'High-dose systemic corticosteroids as the preferred next step given persistent proteinuria', false, $x$Ruled out because systemic corticosteroid therapy in IgA nephropathy carries significant toxicity, and this patient's biopsy features (no crescents, low-risk MEST-C) do not indicate the more aggressive disease phenotype where systemic immunosuppression's risk-benefit would favour its use; targeted-release budesonide offers a more favourable option in this setting.$x$, 2),
('dd000000-0000-0000-0000-000000000032', 'C', 'Cyclophosphamide-based immunosuppression as first-line therapy for residual proteinuria', false, $x$Ruled out because cyclophosphamide carries substantial toxicity and is generally reserved for rapidly progressive, crescentic IgA nephropathy, not for this patient's stable, low-risk, non-crescentic presentation with residual proteinuria on optimised supportive therapy.$x$, 3),
('dd000000-0000-0000-0000-000000000032', 'D', 'Discontinue the SGLT2 inhibitor since proteinuria has not fully resolved', false, 'Ruled out because SGLT2 inhibitors provide ongoing renoprotective benefit independent of complete proteinuria remission and should be continued as part of supportive therapy, not stopped.', 4),
('dd000000-0000-0000-0000-000000000032', 'E', 'Tonsillectomy as the most effective next intervention for reducing proteinuria', false, 'Ruled out because although tonsillectomy has been studied (particularly in some East Asian cohorts) with mixed evidence, it is not a mainstream, guideline-recommended intervention in this context, and targeted-release budesonide has stronger, more broadly applicable trial evidence.', 5),
('dd000000-0000-0000-0000-000000000033', 'A', 'Plasma exchange should be routinely added for all patients with ANCA-associated vasculitis and renal involvement, regardless of severity', false, 'Ruled out because the PEXIVAS trial showed no overall benefit of routine plasma exchange in reducing death or end-stage kidney disease across the general population of ANCA-associated vasculitis patients with severe renal involvement; its use is more selectively considered for severe pulmonary haemorrhage.', 1),
('dd000000-0000-0000-0000-000000000033', 'B', 'Withhold rituximab and cyclophosphamide, treating with corticosteroids and plasma exchange alone', false, 'Ruled out because rituximab or cyclophosphamide-based induction immunosuppression remains essential for ANCA-associated vasculitis with severe organ involvement; plasma exchange is an adjunct, not a substitute for standard induction immunosuppression.', 2),
('dd000000-0000-0000-0000-000000000033', 'C', 'Plasma exchange, given the presence of severe pulmonary haemorrhage requiring oxygen', true, 'Correct. Based on evidence including the PEXIVAS trial, plasma exchange in ANCA-associated vasculitis has not shown overall benefit in preventing death or end-stage kidney disease for the general population of patients with severe renal disease, but it retains a role as an adjunct in selected patients with severe diffuse alveolar haemorrhage (particularly with hypoxaemia), where it can be used to help control life-threatening pulmonary bleeding, alongside standard rituximab/cyclophosphamide and corticosteroid induction.', 3),
('dd000000-0000-0000-0000-000000000033', 'D', 'Avoid any further immunosuppression given the risk of infection with severe pulmonary haemorrhage', false, 'Ruled out because untreated ANCA-associated vasculitis with pulmonary haemorrhage and rapidly progressive renal failure is life-threatening, and standard immunosuppressive induction (rituximab or cyclophosphamide plus corticosteroids) is essential despite infection risk, which is mitigated with appropriate prophylaxis and monitoring.', 4),
('dd000000-0000-0000-0000-000000000033', 'E', 'Proceed directly to renal replacement therapy as the sole management strategy', false, 'Ruled out because although this patient may ultimately need renal replacement therapy given the severity of renal involvement, this does not replace the need for immunosuppressive induction therapy aimed at controlling the underlying vasculitis and potentially recovering renal function.', 5),
('dd000000-0000-0000-0000-000000000034', 'A', 'Hydroxychloroquine monotherapy as sufficient induction therapy for class IV disease', false, 'Ruled out because hydroxychloroquine, while a foundational background therapy for all lupus patients, is not sufficient as sole induction therapy for proliferative class IV lupus nephritis, which requires more potent immunosuppression.', 1),
('dd000000-0000-0000-0000-000000000034', 'B', 'Mycophenolate mofetil combined with corticosteroids as induction therapy', true, $x$Correct. For proliferative (class III/IV) lupus nephritis, mycophenolate mofetil combined with corticosteroids is an established, guideline-recommended induction regimen with efficacy comparable to cyclophosphamide-based regimens but a generally more favourable side-effect profile, particularly relevant in a woman of childbearing age given cyclophosphamide's gonadotoxicity, and is now often used as a preferred first-line induction option (sometimes combined further with belimumab or voclosporin in escalating regimens).$x$, 2),
('dd000000-0000-0000-0000-000000000034', 'C', 'No specific renal-directed immunosuppression is required beyond NSAIDs for proteinuria control', false, 'Ruled out because active proliferative lupus nephritis (class IV, high activity index) requires prompt immunosuppressive induction therapy to prevent progressive, irreversible renal damage; NSAIDs have no role and could worsen renal function.', 3),
('dd000000-0000-0000-0000-000000000034', 'D', 'Rituximab monotherapy as the preferred first-line induction regimen for class IV lupus nephritis', false, 'Ruled out because although rituximab has a role in refractory or relapsing lupus nephritis, it is not the standard first-line induction agent for newly diagnosed proliferative lupus nephritis; mycophenolate mofetil or cyclophosphamide with corticosteroids remain the standard first-line regimens.', 4),
('dd000000-0000-0000-0000-000000000034', 'E', 'Plasma exchange alone as definitive treatment for class IV lupus nephritis', false, 'Ruled out because plasma exchange is not an established primary treatment for lupus nephritis; standard immunosuppressive induction with mycophenolate mofetil or cyclophosphamide plus corticosteroids is required.', 5),
('dd000000-0000-0000-0000-000000000035', 'A', 'Rituximab monotherapy as the preferred first-line treatment', false, 'Ruled out because although rituximab has been used in some anti-GBM disease cases (particularly when cyclophosphamide is contraindicated), the standard, best-evidenced first-line combination remains plasma exchange with corticosteroids and cyclophosphamide, especially in this severe, life-threatening presentation.', 1),
('dd000000-0000-0000-0000-000000000035', 'B', 'Corticosteroids alone, reserving plasma exchange for cases that fail to respond', false, 'Ruled out because in anti-GBM disease with severe pulmonary haemorrhage and rapidly progressive renal failure, plasma exchange should be started immediately alongside corticosteroids and cyclophosphamide, not held in reserve, given the aggressive, antibody-mediated nature of this disease and narrow window for renal recovery.', 2),
('dd000000-0000-0000-0000-000000000035', 'C', 'Watchful waiting with supportive care only, given the poor prognosis for renal recovery at this creatinine level', false, 'Ruled out because prompt combination therapy can still improve outcomes, particularly for pulmonary haemorrhage control and potentially some renal recovery, and this life-threatening presentation mandates urgent active treatment rather than supportive care alone.', 3),
('dd000000-0000-0000-0000-000000000035', 'D', 'Urgent plasma exchange combined with high-dose corticosteroids and cyclophosphamide', true, 'Correct. Anti-GBM disease (Goodpasture syndrome) with pulmonary haemorrhage and rapidly progressive renal failure is a medical emergency requiring immediate combination therapy: plasma exchange to rapidly remove pathogenic circulating anti-GBM antibodies, together with high-dose corticosteroids and cyclophosphamide to suppress further antibody production, ideally started before renal biopsy confirmation is even available if the clinical suspicion is strong, given the narrow window for renal recovery and life-threatening pulmonary involvement.', 4),
('dd000000-0000-0000-0000-000000000035', 'E', 'Haemodialysis alone without any immunosuppressive or antibody-removal therapy', false, 'Ruled out because dialysis may be needed to support the patient through renal failure but does not address the underlying antibody-mediated disease process; combination immunosuppression and plasma exchange are essential to arrest ongoing pulmonary and renal injury.', 5),
('dd000000-0000-0000-0000-000000000036', 'A', 'Increase maintenance immunosuppression to treat presumed acute cellular rejection', false, 'Ruled out because the biopsy specifically shows FSGS with diffuse foot process effacement and no evidence of rejection; this is recurrent primary disease, not rejection, and requires a different treatment approach (plasmapheresis) rather than simply intensifying standard anti-rejection immunosuppression.', 1),
('dd000000-0000-0000-0000-000000000036', 'B', 'Discontinue all immunosuppression and prepare for graft nephrectomy', false, 'Ruled out because recurrent FSGS can respond to targeted therapy (plasmapheresis, rituximab), and discontinuing immunosuppression would risk acute rejection and graft loss without first attempting appropriate treatment for the recurrence.', 2),
('dd000000-0000-0000-0000-000000000036', 'C', 'Reassure the patient that recurrence of FSGS in the graft is expected to resolve spontaneously without treatment', false, 'Ruled out because untreated recurrent FSGS with heavy proteinuria carries a significant risk of progressive graft dysfunction and loss; active treatment (plasmapheresis) is indicated rather than watchful waiting.', 3),
('dd000000-0000-0000-0000-000000000036', 'D', 'Plasmapheresis (plasma exchange), aiming to remove a putative circulating permeability factor', true, 'Correct. Early, severe post-transplant recurrence of primary FSGS, particularly with diffuse foot process effacement without rejection, is thought to be mediated by a circulating permeability factor. Plasmapheresis is the standard first-line treatment aiming to remove this factor and reduce proteinuria, sometimes combined with high-dose corticosteroids and/or rituximab, and can achieve remission in a meaningful proportion of cases if started promptly.', 4),
('dd000000-0000-0000-0000-000000000036', 'E', 'Start an SGLT2 inhibitor as the primary treatment for this recurrence', false, 'Ruled out because while SGLT2 inhibitors have a role in general proteinuric CKD management, they are not the primary, disease-specific treatment for acute post-transplant recurrence of primary FSGS thought to be driven by a circulating permeability factor; plasmapheresis is the appropriate first-line approach.', 5),
('dd000000-0000-0000-0000-000000000037', 'A', 'Plasma exchange and intravenous immunoglobulin as first-line therapy', false, 'Ruled out because plasma exchange and IVIG are primarily used for antibody-mediated rejection (typically C4d-positive, with donor-specific antibodies), not for this C4d-negative, T-cell mediated cellular rejection, where corticosteroids are first-line.', 1),
('dd000000-0000-0000-0000-000000000037', 'B', 'Reduce tacrolimus dose because the trough level, while in range, may still be contributing to toxicity', false, 'Ruled out because the biopsy findings (tubulitis, interstitial infiltrate, no isometric vacuolisation or other calcineurin toxicity features described) support rejection rather than calcineurin inhibitor toxicity, and reducing immunosuppression in the context of rejection would be counterproductive.', 2),
('dd000000-0000-0000-0000-000000000037', 'C', 'Pulsed intravenous methylprednisolone', true, 'Correct. This biopsy picture (interstitial infiltrate with tubulitis, no vasculitis, C4d negative) is characteristic of acute T-cell mediated (cellular) rejection. First-line treatment for grade I-II acute cellular rejection is pulsed intravenous corticosteroids (typically methylprednisolone), with escalation to T-cell depleting agents (e.g. anti-thymocyte globulin) reserved for steroid-resistant or more severe (grade III, with vasculitis) rejection.', 3),
('dd000000-0000-0000-0000-000000000037', 'D', 'Immediate graft nephrectomy given the biopsy findings', false, 'Ruled out because acute cellular rejection of this grade is generally treatable with pulsed corticosteroids, and nephrectomy is not indicated as an initial response to a treatable rejection episode.', 4),
('dd000000-0000-0000-0000-000000000037', 'E', 'Observation only, as tacrolimus levels are therapeutic and no intervention is required', false, 'Ruled out because biopsy-proven acute rejection with tubulitis requires active treatment (pulsed corticosteroids) rather than observation alone, regardless of a therapeutic tacrolimus trough level, since the rejection episode itself needs to be treated to preserve graft function.', 5),
('dd000000-0000-0000-0000-000000000038', 'A', 'Pulsed intravenous methylprednisolone alone as first-line therapy', false, 'Ruled out because corticosteroids alone are the standard for T-cell mediated rejection, not for antibody-mediated rejection, which requires antibody-targeted strategies (plasma exchange, IVIG, rituximab) given the C4d positivity and donor-specific antibodies present here.', 1),
('dd000000-0000-0000-0000-000000000038', 'B', 'Plasma exchange combined with intravenous immunoglobulin, with consideration of rituximab', true, 'Correct. This biopsy picture (peritubular capillaritis, glomerulitis, C4d positivity) alongside high-titre donor-specific antibodies confirms active antibody-mediated rejection. Standard treatment combines plasma exchange (to remove circulating donor-specific antibody) with intravenous immunoglobulin (immunomodulatory effect, and replaces immunoglobulin removed by plasma exchange), with rituximab (targeting B cells) often added, particularly for more severe or refractory cases; bortezomib or newer complement-targeted agents may be considered in some centres for refractory disease.', 2),
('dd000000-0000-0000-0000-000000000038', 'C', 'Increase maintenance tacrolimus dose alone without additional antibody-directed therapy', false, 'Ruled out because simply increasing baseline calcineurin inhibitor dosing does not adequately address established antibody-mediated rejection, which requires specific antibody-removal and B-cell/plasma cell-targeted therapies.', 3),
('dd000000-0000-0000-0000-000000000038', 'D', 'Discontinue all immunosuppression given the severity of rejection', false, 'Ruled out because discontinuing immunosuppression would guarantee graft loss and worsen the alloimmune response; active, targeted treatment of the antibody-mediated rejection is indicated instead.', 4),
('dd000000-0000-0000-0000-000000000038', 'E', 'Observation with repeat biopsy in 4 weeks before considering treatment', false, 'Ruled out because active antibody-mediated rejection with rising creatinine requires prompt treatment to try to preserve graft function; delaying treatment for a repeat biopsy risks irreversible graft injury.', 5),
('dd000000-0000-0000-0000-000000000039', 'A', 'Increase immunosuppression to control the associated interstitial inflammation seen on biopsy', false, 'Ruled out because the interstitial inflammation in BK virus nephropathy reflects viral cytopathic injury, not primarily alloimmune rejection, and increasing immunosuppression would worsen viral replication and graft injury; reduction of immunosuppression is the correct approach.', 1),
('dd000000-0000-0000-0000-000000000039', 'B', 'Start ganciclovir as first-line antiviral therapy for BK virus nephropathy', false, 'Ruled out because there is no antiviral agent with clearly proven efficacy specifically against BK virus (ganciclovir is used for CMV, not BK virus), and the primary evidence-based intervention remains reduction of immunosuppression, sometimes combined with adjuncts like leflunomide, cidofovir, or IVIG in refractory cases with less robust evidence.', 2),
('dd000000-0000-0000-0000-000000000039', 'C', 'Perform urgent graft nephrectomy given biopsy-confirmed viral nephropathy', false, 'Ruled out because BK virus nephropathy can often be controlled with immunosuppression reduction, and nephrectomy is not the standard initial approach; it would be considered only in extreme, refractory circumstances.', 3),
('dd000000-0000-0000-0000-000000000039', 'D', 'Continue current immunosuppression unchanged and monitor BK viral load without intervention', false, 'Ruled out because established BK virus nephropathy with rising creatinine requires active reduction of immunosuppression to allow immune clearance of the virus; simply monitoring without intervention risks progressive graft loss.', 4),
('dd000000-0000-0000-0000-000000000039', 'E', 'Reduce the overall intensity of maintenance immunosuppression, typically by lowering or stopping the antimetabolite and/or reducing the calcineurin inhibitor dose', true, 'Correct. The mainstay of treatment for BK virus-associated nephropathy is a graded reduction in overall immunosuppression to allow host immune control of viral replication, typically achieved by reducing or discontinuing the antimetabolite (mycophenolate mofetil) first and/or reducing calcineurin inhibitor exposure, with close monitoring of plasma BK viral load and graft function, balanced against the competing risk of rejection.', 5),
('dd000000-0000-0000-0000-000000000040', 'A', 'Treatment-dose valganciclovir (or intravenous ganciclovir if severe), with reduction of antimetabolite immunosuppression if appropriate', true, 'Correct. This is CMV disease (symptomatic CMV infection with organ involvement, here likely CMV colitis, plus viraemia) in a high-risk donor-positive/recipient-negative mismatch. Treatment requires therapeutic-dose valganciclovir (oral) or intravenous ganciclovir for more severe disease, alongside consideration of temporarily reducing antimetabolite immunosuppression (e.g. mycophenolate) to aid immune clearance of the virus, with close monitoring of viral load to guide duration of therapy.', 1),
('dd000000-0000-0000-0000-000000000040', 'B', 'Continue current immunosuppression unchanged and start prophylactic-dose valganciclovir', false, 'Ruled out because established CMV disease with organ involvement requires treatment-dose antiviral therapy, not prophylactic dosing, which is insufficient to treat active disease; immunosuppression reduction should also be considered.', 2),
('dd000000-0000-0000-0000-000000000040', 'C', 'Stop all antiviral considerations since CMV IgG mismatch prophylaxis should already have prevented this', false, 'Ruled out because breakthrough CMV disease can still occur despite prophylaxis or even without adequate prophylaxis, and active CMV disease requires prompt treatment-dose antiviral therapy regardless of prior preventive strategy.', 3),
('dd000000-0000-0000-0000-000000000040', 'D', 'Increase immunosuppression to control the diarrhoea, presuming this represents rejection-related colitis', false, 'Ruled out because the clinical and laboratory picture (fever, leukopenia, diarrhoea, high CMV viral load) is characteristic of CMV disease, not rejection; increasing immunosuppression would worsen viral replication and is inappropriate here.', 4),
('dd000000-0000-0000-0000-000000000040', 'E', 'Perform immediate graft biopsy as the priority before starting any antiviral therapy', false, 'Ruled out because the diagnosis of CMV disease is strongly supported by the clinical syndrome and viral load without requiring graft biopsy first; prompt antiviral treatment should not be delayed for biopsy in this context, though tissue diagnosis (e.g. colonic biopsy) may sometimes support the diagnosis of end-organ disease.', 5),
('dd000000-0000-0000-0000-000000000041', 'A', 'Reduce the tacrolimus dose and closely monitor renal function and trough levels', true, 'Correct. The biopsy findings described (isometric tubular vacuolisation, arteriolar hyalinosis, without inflammation, tubulitis, or C4d positivity) are characteristic of calcineurin inhibitor (tacrolimus) toxicity rather than rejection, consistent with the supratherapeutic trough level. Management is dose reduction with close monitoring of levels and renal function, as toxicity is often reversible with appropriate dose adjustment.', 1),
('dd000000-0000-0000-0000-000000000041', 'B', 'Increase the tacrolimus dose to ensure adequate immunosuppression given the rising creatinine', false, 'Ruled out because increasing an already supratherapeutic tacrolimus dose would worsen calcineurin inhibitor nephrotoxicity, which is the cause of the renal dysfunction based on the biopsy findings, not under-immunosuppression.', 2),
('dd000000-0000-0000-0000-000000000041', 'C', 'Start pulsed intravenous methylprednisolone for presumed acute rejection', false, 'Ruled out because the biopsy specifically lacks features of rejection (no significant interstitial inflammation, tubulitis, or C4d positivity), instead showing classic calcineurin inhibitor toxicity changes; treating this as rejection would not address the actual cause and unnecessarily exposes the patient to additional immunosuppression.', 3),
('dd000000-0000-0000-0000-000000000041', 'D', 'Switch immediately to plasma exchange and IVIG for antibody-mediated rejection', false, 'Ruled out because there is no C4d positivity or evidence of antibody-mediated rejection; the biopsy is consistent with calcineurin inhibitor toxicity, and plasma exchange/IVIG is not indicated.', 4),
('dd000000-0000-0000-0000-000000000041', 'E', 'Stop all immunosuppression to allow the kidney to recover from toxicity', false, 'Ruled out because stopping immunosuppression entirely would risk acute rejection; the appropriate management for calcineurin inhibitor toxicity is dose reduction and careful monitoring, not complete cessation of immunosuppression.', 5),
('dd000000-0000-0000-0000-000000000042', 'A', 'Immediately discontinue tacrolimus and switch to an alternative immunosuppressant regardless of rejection risk', false, 'Ruled out because abrupt discontinuation of a calcineurin inhibitor this early post-transplant carries a significant rejection risk; any adjustment to diabetogenic immunosuppression should be considered cautiously and gradually, balanced against graft protection, not as an immediate blanket discontinuation.', 1),
('dd000000-0000-0000-0000-000000000042', 'B', 'No specific action is required as post-transplant diabetes generally resolves spontaneously without intervention', false, 'Ruled out because post-transplant diabetes mellitus is associated with increased cardiovascular risk and reduced graft/patient survival if left untreated, and requires active management rather than being expected to resolve spontaneously.', 2),
('dd000000-0000-0000-0000-000000000042', 'C', 'Start insulin therapy immediately as the only appropriate first-line treatment, bypassing lifestyle measures and oral agents', false, 'Ruled out because for this degree of hyperglycaemia, lifestyle measures and consideration of oral glucose-lowering therapy (if renal function is adequate) are reasonable initial approaches, with insulin reserved for more severe or refractory hyperglycaemia.', 3),
('dd000000-0000-0000-0000-000000000042', 'D', 'Optimise lifestyle measures and consider minimising diabetogenic immunosuppression (e.g. reducing tacrolimus exposure or corticosteroid dose) where feasible, alongside standard glucose-lowering therapy as needed', true, 'Correct. New-onset diabetes after transplantation is a recognised complication of immunosuppressive therapy (tacrolimus and corticosteroids both being diabetogenic, tacrolimus more so than ciclosporin). Initial management includes lifestyle modification, cautious minimisation of diabetogenic immunosuppressive exposure where this can be done without increasing rejection risk, and standard glucose-lowering therapy (metformin if renal function allows, or other agents) as needed, with close monitoring of both glycaemic control and graft function/rejection risk.', 4),
('dd000000-0000-0000-0000-000000000042', 'E', 'Increase corticosteroid dose to help control inflammation-related insulin resistance', false, 'Ruled out because corticosteroids are themselves diabetogenic and increasing the dose would worsen, not improve, the hyperglycaemia.', 5),
('dd000000-0000-0000-0000-000000000043', 'A', 'Immediate surgical re-exploration for presumed vascular thrombosis', false, 'Ruled out because Doppler ultrasound has already confirmed good vascular flow without thrombosis, making urgent surgical re-exploration for vascular occlusion inappropriate; the clinical picture instead fits ischaemia-reperfusion-related delayed graft function.', 1),
('dd000000-0000-0000-0000-000000000043', 'B', 'Start pulsed corticosteroids immediately for presumed hyperacute rejection', false, 'Ruled out because hyperacute rejection occurs within minutes to hours of reperfusion due to preformed antibodies and typically shows graft mottling/thrombosis intraoperatively, which is not the picture here; delayed graft function from ischaemia-reperfusion injury is a much more likely explanation given the donor risk factors described.', 2),
('dd000000-0000-0000-0000-000000000043', 'C', 'Delayed graft function due to ischaemia-reperfusion injury (acute tubular necrosis of the graft); manage supportively with dialysis as needed while avoiding nephrotoxic exposures and over-immunosuppression, since function usually recovers over days to weeks', true, 'Correct. Delayed graft function, most commonly due to ischaemia-reperfusion injury (a form of acute tubular necrosis) related to donor instability and prolonged cold ischaemic time, is a well-recognised complication with normal vascular flow and no obstruction on Doppler ultrasound. Management is supportive (dialysis if needed for uraemic complications, careful fluid balance, avoidance of additional nephrotoxins, and cautious immunosuppression to avoid masking or precipitating rejection while awaiting tubular recovery, which usually occurs over days to a few weeks).', 3),
('dd000000-0000-0000-0000-000000000043', 'D', 'Perform emergency graft nephrectomy given the lack of urine output', false, 'Ruled out because delayed graft function due to ischaemia-reperfusion injury commonly recovers with supportive management over days to weeks, and nephrectomy is not indicated for this expected, generally reversible complication.', 4),
('dd000000-0000-0000-0000-000000000043', 'E', 'Increase calcineurin inhibitor dosing significantly to protect the graft during this period', false, 'Ruled out because supratherapeutic calcineurin inhibitor exposure can worsen tubular injury and prolong delayed graft function; cautious, often reduced, calcineurin inhibitor dosing with careful monitoring is generally preferred during this period.', 5),
('dd000000-0000-0000-0000-000000000044', 'A', 'High-dose loop diuretic therapy to reduce nephrocalcinosis progression', false, 'Ruled out because loop diuretics increase urinary calcium excretion and would worsen, not improve, nephrocalcinosis and stone risk; they have no role in treating the underlying tubular acidification defect.', 1),
('dd000000-0000-0000-0000-000000000044', 'B', 'Oral sodium bicarbonate or potassium citrate supplementation to correct the acidosis and reduce nephrocalcinosis/stone risk', true, $x$Correct. This picture (hypokalaemic, normal-anion-gap metabolic acidosis with an inappropriately alkaline urine pH despite systemic acidaemia, nephrocalcinosis, and an underlying autoimmune condition associated with distal RTA such as Sjogren's syndrome) is characteristic of distal (type 1) renal tubular acidosis, caused by impaired distal tubular hydrogen ion secretion. Long-term management is alkali replacement, typically with potassium citrate (correcting both acidosis and hypokalaemia while reducing urinary calcium phosphate stone/nephrocalcinosis risk) or sodium bicarbonate.$x$, 2),
('dd000000-0000-0000-0000-000000000044', 'C', 'Restrict dietary potassium intake to correct the hypokalaemia', false, 'Ruled out because the hypokalaemia in distal RTA results from renal potassium wasting related to the tubular defect (and secondary hyperaldosteronism from volume effects), not excess dietary intake; dietary restriction would not correct the underlying problem, and alkali therapy itself helps correct the potassium wasting.', 3),
('dd000000-0000-0000-0000-000000000044', 'D', 'Administer intravenous acetazolamide to treat the acidosis', false, 'Ruled out because acetazolamide is a carbonic anhydrase inhibitor that promotes bicarbonate wasting and would worsen the metabolic acidosis; it is used to induce a proximal RTA-like state (e.g. in altitude sickness), not to treat an existing acidosis.', 4),
('dd000000-0000-0000-0000-000000000044', 'E', 'No specific treatment is required beyond monitoring, as this represents an incidental finding', false, 'Ruled out because untreated distal RTA leads to ongoing nephrocalcinosis, recurrent stone formation, bone demineralisation, and potential progressive renal impairment; active alkali replacement therapy is indicated.', 5),
('dd000000-0000-0000-0000-000000000045', 'A', 'Distal (type 1) RTA caused by impaired distal hydrogen ion secretion', false, 'Ruled out because distal RTA does not typically cause the broad pattern of glycosuria, phosphaturia, uricosuria, and aminoaciduria seen here, which instead reflects a generalised proximal tubular defect (Fanconi syndrome) rather than an isolated distal acidification defect.', 1),
('dd000000-0000-0000-0000-000000000045', 'B', 'Type 4 RTA due to aldosterone resistance', false, 'Ruled out because type 4 RTA is characterised by hyperkalaemia (from aldosterone deficiency or resistance) and a milder acidosis, not the broad proximal tubular transport losses (glycosuria, phosphaturia, uricosuria, aminoaciduria) described in this vignette.', 2),
('dd000000-0000-0000-0000-000000000045', 'C', 'Diabetic nephropathy causing glycosuria and tubular dysfunction', false, 'Ruled out because blood glucose is stated to be normal, excluding diabetes as the cause of the glycosuria; the pattern instead reflects a generalised proximal tubular reabsorptive defect from myeloma-related light chain toxicity.', 3),
('dd000000-0000-0000-0000-000000000045', 'D', 'Acute tubular necrosis from chemotherapy nephrotoxicity alone', false, 'Ruled out because although chemotherapy can contribute to renal injury, the specific combination of glycosuria, phosphaturia, uricosuria, and aminoaciduria with acidosis is the classic pattern of Fanconi syndrome from myeloma light chain toxicity, rather than a nonspecific ATN picture.', 4),
('dd000000-0000-0000-0000-000000000045', 'E', 'Proximal (type 2) RTA / Fanconi syndrome, caused by light chain-mediated proximal tubular toxicity impairing bicarbonate reabsorption and other proximal transport functions', true, 'Correct. The combination of glycosuria (with normal glucose), phosphaturia, uricosuria, aminoaciduria, and a hyperchloraemic metabolic acidosis reflects generalised proximal tubular dysfunction (Fanconi syndrome), here driven by nephrotoxic free light chains from multiple myeloma damaging proximal tubular cells and impairing their normal reabsorptive functions, including bicarbonate reabsorption (causing type 2, proximal, RTA).', 5),
('dd000000-0000-0000-0000-000000000046', 'A', 'Type 1 (distal) RTA; treat with potassium citrate supplementation', false, $x$Ruled out because distal RTA classically causes hypokalaemia, not hyperkalaemia; this patient's hyperkalaemic pattern with low aldosterone relative to renin is characteristic of type 4 RTA, not type 1.$x$, 1),
('dd000000-0000-0000-0000-000000000046', 'B', 'Type 4 RTA (hyporeninaemic hypoaldosteronism) related to diabetic nephropathy; manage with dietary potassium restriction and, if needed, a loop diuretic to promote potassium excretion', true, 'Correct. Type 4 RTA, most commonly due to hyporeninaemic hypoaldosteronism in the context of diabetic nephropathy, causes hyperkalaemia with a mild hyperchloraemic metabolic acidosis due to reduced ammoniagenesis from the hyperkalaemia itself impairing distal acidification indirectly. Management includes dietary potassium restriction, avoidance of additional hyperkalaemia-inducing medications, and if needed, a loop or thiazide diuretic to promote urinary potassium excretion; fludrocortisone is used cautiously in some cases but carries fluid retention risk.', 2),
('dd000000-0000-0000-0000-000000000046', 'C', 'Type 2 (proximal) RTA; treat with sodium bicarbonate and expect a normal potassium', false, 'Ruled out because proximal RTA does not typically cause the hyperkalaemic pattern seen here, and would not be associated with the low aldosterone/renin ratio described; the picture fits type 4 RTA related to diabetic nephropathy.', 3),
('dd000000-0000-0000-0000-000000000046', 'D', 'Primary hyperaldosteronism; arrange adrenal imaging and consider adrenalectomy', false, $x$Ruled out because primary hyperaldosteronism causes hypokalaemia with suppressed renin and elevated aldosterone, the opposite biochemical pattern to this patient's hyperkalaemia with inappropriately low aldosterone relative to renin.$x$, 4),
('dd000000-0000-0000-0000-000000000046', 'E', $x$Addison's disease; start hydrocortisone and fludrocortisone replacement$x$, false, $x$Ruled out because Addison's disease causes both glucocorticoid and mineralocorticoid deficiency typically with hyponatraemia and more marked acidosis/hypotension, whereas this patient's picture (isolated hypoaldosteronism in the context of diabetic nephropathy with normal-to-high renin) is specific to type 4 RTA rather than primary adrenal insufficiency.$x$, 5),
('dd000000-0000-0000-0000-000000000047', 'A', 'Gitelman syndrome', false, $x$Ruled out because Gitelman syndrome, from a distal convoluted tubule sodium-chloride co-transporter defect (mimicking thiazide diuretic use), characteristically causes hypocalciuria and hypomagnesaemia, and does not typically cause nephrocalcinosis; this patient's hypercalciuria with nephrocalcinosis points to Bartter syndrome instead.$x$, 1),
('dd000000-0000-0000-0000-000000000047', 'B', 'Liddle syndrome', false, 'Ruled out because Liddle syndrome causes hypertension with hypokalaemic metabolic alkalosis and suppressed (not elevated) renin and aldosterone, due to a gain-of-function epithelial sodium channel mutation; this patient has normal blood pressure with markedly elevated renin and aldosterone, the opposite pattern.', 2),
('dd000000-0000-0000-0000-000000000047', 'C', 'Bartter syndrome', true, $x$Correct. Bartter syndrome results from a defect in the loop of Henle's sodium-potassium-2-chloride co-transporter (or associated channels), mimicking the effect of chronic loop diuretic use: hypokalaemic metabolic alkalosis, normal blood pressure, secondary hyperreninaemic hyperaldosteronism, and increased urinary calcium excretion leading to nephrocalcinosis, distinguishing it from Gitelman syndrome, which characteristically causes hypocalciuria rather than hypercalciuria.$x$, 3),
('dd000000-0000-0000-0000-000000000047', 'D', 'Primary hyperaldosteronism', false, 'Ruled out because primary hyperaldosteronism causes hypertension with suppressed renin, not the normal blood pressure with markedly elevated renin and aldosterone seen in this patient, which indicates a renal tubular salt-losing disorder rather than primary adrenal pathology.', 4),
('dd000000-0000-0000-0000-000000000047', 'E', $x$Conn's syndrome secondary to a renin-secreting tumour$x$, false, 'Ruled out because although renin-secreting tumours can cause hypertension with elevated renin and secondary hyperaldosteronism, this patient has normal blood pressure and the clinical picture (failure to thrive, nephrocalcinosis, polyuria from early childhood) is far more consistent with an inherited renal tubulopathy such as Bartter syndrome.', 5),
('dd000000-0000-0000-0000-000000000048', 'A', 'Bartter syndrome; calcium should be prioritised for correction given the expected hypercalciuria', false, 'Ruled out because this patient has hypocalciuria, not hypercalciuria, which specifically points away from Bartter syndrome (characteristically hypercalciuric) towards Gitelman syndrome (characteristically hypocalciuric); calcium correction is also not the relevant priority in this electrolyte picture.', 1),
('dd000000-0000-0000-0000-000000000048', 'B', 'Liddle syndrome; sodium restriction and amiloride are the priority interventions', false, $x$Ruled out because Liddle syndrome causes hypertension with suppressed renin and aldosterone due to a sodium channel gain-of-function mutation, which does not match this patient's normal blood pressure and elevated renin/aldosterone; the hypomagnesaemia and hypocalciuria described are also not features of Liddle syndrome.$x$, 2),
('dd000000-0000-0000-0000-000000000048', 'C', 'Primary aldosteronism; adrenal venous sampling should be the priority investigation', false, 'Ruled out because primary aldosteronism causes hypertension with suppressed renin, not the normotension with elevated renin and aldosterone seen here, and does not typically cause the hypomagnesaemia and hypocalciuria described, which are specific features of Gitelman syndrome.', 3),
('dd000000-0000-0000-0000-000000000048', 'D', 'Distal renal tubular acidosis; potassium citrate should be the priority treatment', false, 'Ruled out because distal RTA causes metabolic acidosis, not the metabolic alkalosis described here, and does not account for the hypomagnesaemia and hypocalciuria pattern, which are specific to Gitelman syndrome.', 4),
('dd000000-0000-0000-0000-000000000048', 'E', 'Gitelman syndrome; magnesium should be replaced, as hypomagnesaemia can perpetuate the potassium wasting and make hypokalaemia refractory to correction', true, 'Correct. Gitelman syndrome, from a defect in the distal convoluted tubule thiazide-sensitive NaCl co-transporter, characteristically presents with hypokalaemic metabolic alkalosis, normal blood pressure, mild secondary hyperreninaemic hyperaldosteronism, hypomagnesaemia, and hypocalciuria (distinguishing it from Bartter syndrome). Correcting magnesium deficiency is important because persistent hypomagnesaemia impairs renal potassium conservation and can make hypokalaemia refractory to potassium supplementation alone.', 5),
('dd000000-0000-0000-0000-000000000049', 'A', 'Amiloride (or triamterene), a direct epithelial sodium channel blocker', true, 'Correct. Liddle syndrome is caused by a gain-of-function mutation in the epithelial sodium channel (ENaC) in the distal nephron, causing constitutive sodium reabsorption and potassium/hydrogen secretion independent of aldosterone, producing hypertension with hypokalaemic alkalosis and suppressed renin/aldosterone. Because the defect is in the channel itself (not aldosterone-driven), treatment requires a direct ENaC blocker such as amiloride or triamterene, rather than a mineralocorticoid receptor antagonist, which would be ineffective since aldosterone is already suppressed and not driving the channel activity.', 1),
('dd000000-0000-0000-0000-000000000049', 'B', 'Spironolactone, a mineralocorticoid receptor antagonist', false, 'Ruled out because spironolactone works by blocking the aldosterone receptor, but in Liddle syndrome the epithelial sodium channel is constitutively active independent of aldosterone (which is already suppressed); spironolactone is therefore ineffective, and a direct channel blocker (amiloride) is required.', 2),
('dd000000-0000-0000-0000-000000000049', 'C', 'An ACE inhibitor as first-line antihypertensive therapy', false, 'Ruled out because ACE inhibitors act on the renin-angiotensin system, which is already suppressed in Liddle syndrome, making them a poor mechanistic choice; a direct ENaC blocker (amiloride) targets the actual underlying defect.', 3),
('dd000000-0000-0000-0000-000000000049', 'D', 'Fludrocortisone to restore appropriate mineralocorticoid activity', false, 'Ruled out because Liddle syndrome results from a channel defect causing effects that mimic mineralocorticoid excess even though aldosterone is suppressed; giving additional mineralocorticoid (fludrocortisone) would worsen the hypertension and hypokalaemia.', 4),
('dd000000-0000-0000-0000-000000000049', 'E', 'High-dose potassium supplementation alone, without any specific channel-blocking therapy', false, 'Ruled out because potassium supplementation alone does not address the underlying constitutive sodium channel activity driving both the hypertension and the ongoing potassium wasting; amiloride, which blocks the channel directly, is required for durable correction of both problems.', 5),
('dd000000-0000-0000-0000-000000000050', 'A', 'A thiazide diuretic to reduce urinary calcium excretion', false, 'Ruled out because cystinuria is not primarily a calcium stone disorder; thiazides reduce calcium stone risk in idiopathic hypercalciuria but do not address the specific cystine solubility problem in cystinuria.', 1),
('dd000000-0000-0000-0000-000000000050', 'B', 'Allopurinol to reduce uric acid stone formation', false, 'Ruled out because the stone analysis and clinical picture (hexagonal crystals, positive cyanide-nitroprusside test) indicate cystine stones, not uric acid stones, so allopurinol (which reduces urate production) is not the relevant therapy here.', 2),
('dd000000-0000-0000-0000-000000000050', 'C', 'Potassium citrate alone as definitive long-term therapy without need for further agents', false, 'Ruled out because although urinary alkalinisation (often with potassium citrate) increases cystine solubility and is a useful conservative measure, it is often insufficient alone for recurrent stone formers, who then require thiol-based chelating agents as add-on therapy.', 3),
('dd000000-0000-0000-0000-000000000050', 'D', 'A thiol-containing chelating agent such as tiopronin or D-penicillamine, which binds cysteine to form a more soluble complex', true, 'Correct. This presentation (recurrent radiolucent stones from adolescence, hexagonal crystals on stone analysis, positive cyanide-nitroprusside test, family history) is characteristic of cystinuria, an autosomal recessive disorder of defective renal (and intestinal) transport of cystine and dibasic amino acids. When high fluid intake and urinary alkalinisation are insufficient to prevent recurrent stones, thiol-based chelating agents (tiopronin generally preferred over D-penicillamine due to a better side-effect profile) bind cysteine to form a more soluble cysteine-drug complex, reducing cystine crystallisation.', 4),
('dd000000-0000-0000-0000-000000000050', 'E', 'Calcium supplementation to bind excess urinary cystine', false, 'Ruled out because calcium supplementation has no established role in reducing cystine stone formation and is not part of standard cystinuria management.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('dd000000-0000-0000-0000-000000000001', 'Periprocedural isotonic crystalloid remains the best-evidenced intervention for reducing contrast-associated AKI in high-risk (CKD, diabetes) patients undergoing iodinated contrast studies.', 1),
('dd000000-0000-0000-0000-000000000001', 'Metformin should be withheld around contrast exposure in patients with reduced eGFR because of the risk of lactic acidosis if AKI supervenes, then restarted once renal function is confirmed stable.', 2),
('dd000000-0000-0000-0000-000000000001', 'A time-critical diagnostic study (e.g. suspected PE) should not be delayed for nephroprotective measures such as N-acetylcysteine, which lack robust outcome benefit.', 3),
('dd000000-0000-0000-0000-000000000002', 'Rhabdomyolysis causes AKI through myoglobin cast nephropathy, and can produce rapid, severe hyperkalaemia disproportionate to the degree of renal impairment because of massive intracellular potassium release from damaged muscle.', 1),
('dd000000-0000-0000-0000-000000000002', 'Oliguric AKI with severe or refractory hyperkalaemia despite medical therapy and adequate fluid resuscitation is an indication for urgent renal replacement therapy, which should not be delayed.', 2),
('dd000000-0000-0000-0000-000000000002', 'Urinary alkalinisation and forced diuresis are commonly cited historical measures for rhabdomyolysis but lack robust evidence and should not substitute for dialysis when hard indications are present.', 3),
('dd000000-0000-0000-0000-000000000003', 'Hepatorenal syndrome-AKI is a diagnosis of exclusion in cirrhosis with ascites, made after ruling out structural kidney disease, nephrotoxin exposure, sepsis, and a lack of response to volume expansion with albumin and diuretic withdrawal.', 1),
('dd000000-0000-0000-0000-000000000003', 'First-line treatment of HRS-AKI is a splanchnic vasoconstrictor (terlipressin, or noradrenaline in appropriate settings) combined with albumin, aiming to reverse the underlying splanchnic vasodilation and effective hypovolaemia.', 2),
('dd000000-0000-0000-0000-000000000003', 'Renal replacement therapy and liver transplantation are considered for HRS-AKI refractory to vasoconstrictor therapy, not as an initial substitute for it.', 3),
('dd000000-0000-0000-0000-000000000004', 'ECG changes in hyperkalaemia (peaked T waves progressing to widened QRS and loss of P waves) indicate an immediately life-threatening state requiring emergency membrane stabilisation with intravenous calcium before other measures.', 1),
('dd000000-0000-0000-0000-000000000004', 'Insulin-dextrose and salbutamol temporarily shift potassium intracellularly but do not remove potassium from the body; in oliguric AKI, definitive management requires urgent renal replacement therapy.', 2),
('dd000000-0000-0000-0000-000000000004', 'Calcium resonium and other cation exchangers act too slowly to have any role in the emergency management of severe, ECG-positive hyperkalaemia.', 3),
('dd000000-0000-0000-0000-000000000005', 'Fractional excretion of sodium becomes unreliable in patients recently treated with diuretics, because diuretics obligately increase renal sodium excretion independent of the underlying cause of AKI.', 1),
('dd000000-0000-0000-0000-000000000005', 'Fractional excretion of urea is less influenced by loop or thiazide diuretics and is preferred over fractional excretion of sodium for distinguishing prerenal AKI from acute tubular necrosis in diuretic-treated patients.', 2),
('dd000000-0000-0000-0000-000000000005', 'A low fractional excretion of urea suggests intact tubular reabsorption (prerenal physiology), while a higher value suggests tubular injury (ATN), though clinical context always takes priority over any single index.', 3),
('dd000000-0000-0000-0000-000000000006', 'Cardiorenal syndrome in decompensated heart failure often causes rising creatinine driven by renal venous congestion and reduced perfusion pressure rather than intravascular volume depletion, so diuretics should not automatically be stopped for a rising creatinine in a still-congested patient.', 1),
('dd000000-0000-0000-0000-000000000006', 'Sequential nephron blockade (adding a thiazide or thiazide-like agent to a loop diuretic) is a standard strategy for diuretic resistance and should generally be tried before ultrafiltration.', 2),
('dd000000-0000-0000-0000-000000000006', 'Trial evidence (CARRESS-HF) has not shown isolated ultrafiltration to be superior to a stepped pharmacological diuretic strategy for acute decompensated heart failure with worsening renal function.', 3),
('dd000000-0000-0000-0000-000000000007', 'Calcimimetics (cinacalcet, etelcalcetide) lower PTH via the calcium-sensing receptor while lowering serum calcium, making them preferable to vitamin D receptor activators when secondary hyperparathyroidism coexists with hypercalcaemia.', 1),
('dd000000-0000-0000-0000-000000000007', 'Vitamin D receptor activators increase intestinal calcium and phosphate absorption and can worsen hypercalcaemia/hyperphosphataemia, limiting their use once these are elevated.', 2),
('dd000000-0000-0000-0000-000000000007', 'Parathyroidectomy is reserved for severe secondary/tertiary hyperparathyroidism refractory to optimised medical therapy, including calcimimetics.', 3),
('dd000000-0000-0000-0000-000000000008', 'In CKD, ferritin is an unreliable indicator of true iron stores because of its behaviour as an acute-phase reactant; transferrin saturation better reflects iron available for erythropoiesis.', 1),
('dd000000-0000-0000-0000-000000000008', 'Functional iron deficiency (normal/high ferritin, low transferrin saturation) is a common cause of ESA hyporesponsiveness in CKD, and intravenous iron (preferred over oral due to hepcidin-mediated malabsorption) can improve response.', 2),
('dd000000-0000-0000-0000-000000000008', 'Escalating ESA dose without correcting iron status increases cardiovascular and thrombotic risk without reliably improving haemoglobin.', 3),
('dd000000-0000-0000-0000-000000000009', 'SGLT2 inhibitors provide renoprotection in diabetic and non-diabetic proteinuric CKD via haemodynamic effects on the glomerulus, additive to RAAS blockade, and are now standard add-on therapy once patients are on maximally tolerated ACE inhibitor/ARB.', 1),
('dd000000-0000-0000-0000-000000000009', 'Dual RAAS blockade (combining ACE inhibitor and ARB) increases adverse events (hyperkalaemia, AKI) without added renoprotective benefit and should be avoided.', 2),
('dd000000-0000-0000-0000-000000000009', 'Residual albuminuria despite RAAS blockade identifies patients who benefit most from additional renoprotective therapy such as SGLT2 inhibitors or, in some cases, a non-steroidal mineralocorticoid receptor antagonist.', 3),
('dd000000-0000-0000-0000-000000000010', 'Adynamic bone disease results from oversuppression of PTH (often iatrogenic, from excess vitamin D receptor activator and calcium-based binder use) and presents with low bone turnover, hypercalcaemia, and increased fracture risk.', 1),
('dd000000-0000-0000-0000-000000000010', 'Management of adynamic bone disease involves reducing calcium load and vitamin D receptor activator dosing to allow PTH to rise to an appropriate target range for dialysis patients, restoring normal bone turnover.', 2),
('dd000000-0000-0000-0000-000000000010', 'Osteitis fibrosa (from uncontrolled secondary hyperparathyroidism) and adynamic bone disease sit at opposite ends of the CKD-MBD turnover spectrum and require opposite management strategies.', 3),
('dd000000-0000-0000-0000-000000000011', 'Conservative kidney management is a legitimate, planned alternative to dialysis for appropriately selected patients (e.g. very frail, multiple comorbidities, limited prognosis, or personal preference), focusing on symptom control and quality of life.', 1),
('dd000000-0000-0000-0000-000000000011', 'Evidence suggests dialysis may not confer a survival or quality-of-life advantage over conservative management in very frail elderly patients with high comorbidity burden.', 2),
('dd000000-0000-0000-0000-000000000011', 'Shared decision-making incorporating patient values and preferences, ideally through early and ongoing advance care planning, should guide the choice between dialysis and conservative management in advanced CKD.', 3),
('dd000000-0000-0000-0000-000000000012', 'In dialysis patients with evidence of vascular calcification, non-calcium-based phosphate binders are preferred over calcium-based binders to avoid contributing additional calcium load.', 1),
('dd000000-0000-0000-0000-000000000012', 'Aluminium-containing phosphate binders are avoided for long-term use because of cumulative toxicity risks including osteomalacia and encephalopathy.', 2),
('dd000000-0000-0000-0000-000000000012', 'Phosphate control in CKD-MBD requires a combined approach of dietary phosphate restriction, appropriate binder choice, and adequate dialysis clearance.', 3),
('dd000000-0000-0000-0000-000000000013', 'Drug-induced acute interstitial nephritis classically presents with a subacute AKI, low-grade fever, eosinophilia, and sterile pyuria/leucocyturia, often with a temporal relationship to a new or long-term culprit drug (PPIs, NSAIDs, antibiotics being common causes).', 1),
('dd000000-0000-0000-0000-000000000013', 'The first management step in suspected AIN is withdrawal of the likely causative drug; renal biopsy and corticosteroids are considered if renal function does not recover.', 2),
('dd000000-0000-0000-0000-000000000013', 'Proton pump inhibitors are an increasingly recognised cause of AIN and should be considered even after long-term, previously well-tolerated use.', 3),
('dd000000-0000-0000-0000-000000000014', 'Aminoglycoside nephrotoxicity typically causes non-oliguric acute tubular necrosis due to cumulative proximal tubular drug accumulation, and can occur despite therapeutic trough levels.', 1),
('dd000000-0000-0000-0000-000000000014', 'Risk reduction strategies include extended-interval (once-daily) dosing, minimising treatment duration, and close therapeutic drug monitoring, particularly in patients with other nephrotoxic risk factors.', 2),
('dd000000-0000-0000-0000-000000000014', 'Concurrent nephrotoxins (e.g. NSAIDs, other nephrotoxic antibiotics) should be avoided or minimised when aminoglycoside therapy is required, to reduce cumulative renal injury risk.', 3),
('dd000000-0000-0000-0000-000000000015', 'NSAIDs can rarely cause a combined lesion of acute interstitial nephritis with a minimal change-like nephrotic syndrome, thought to be mediated by NSAID-induced cytokine dysregulation affecting both the tubulointerstitium and podocytes.', 1),
('dd000000-0000-0000-0000-000000000015', 'Management begins with withdrawal of the causative NSAID; corticosteroids are used if nephrotic syndrome or renal impairment persist despite drug cessation.', 2),
('dd000000-0000-0000-0000-000000000015', $x$COX-2 selective inhibitors are not renally 'safe' alternatives to non-selective NSAIDs and carry similar risks of nephrotoxicity.$x$, 3),
('dd000000-0000-0000-0000-000000000016', 'Chronic lithium therapy causes nephrogenic diabetes insipidus through downregulation of aquaporin-2 water channels in the renal collecting duct, producing desmopressin-unresponsive polyuria.', 1),
('dd000000-0000-0000-0000-000000000016', 'Amiloride reduces lithium-induced nephrogenic diabetes insipidus by blocking lithium uptake into collecting duct principal cells via the epithelial sodium channel, allowing continued lithium therapy when clinically necessary.', 2),
('dd000000-0000-0000-0000-000000000016', 'Decisions to stop or continue lithium in a patient with significant psychiatric illness require a joint, multidisciplinary approach with psychiatry rather than unilateral cessation.', 3),
('dd000000-0000-0000-0000-000000000017', 'Tenofovir disoproxil fumarate can cause proximal renal tubulopathy (acquired Fanconi syndrome) through mitochondrial toxicity, presenting with glycosuria (normoglycaemic), phosphaturia, hypokalaemia, low-molecular-weight proteinuria, and normal-anion-gap metabolic acidosis.', 1),
('dd000000-0000-0000-0000-000000000017', 'Management involves switching to a less nephrotoxic antiretroviral option (e.g. tenofovir alafenamide has a more favourable renal profile than tenofovir disoproxil fumarate) in collaboration with HIV specialists, alongside correcting electrolyte derangements.', 2),
('dd000000-0000-0000-0000-000000000017', 'Fanconi syndrome from any cause reflects generalised proximal tubular dysfunction, affecting reabsorption of glucose, phosphate, amino acids, bicarbonate, and low-molecular-weight proteins together.', 3),
('dd000000-0000-0000-0000-000000000018', 'Cholesterol (atheroembolic) embolisation syndrome typically follows arterial instrumentation (angiography, angioplasty, cardiac surgery) by days to weeks, and presents with livedo reticularis, digital/limb ischaemia, eosinophilia, subacute renal impairment, and sometimes mild hypocomplementaemia.', 1),
('dd000000-0000-0000-0000-000000000018', 'Unlike contrast-induced nephropathy, which occurs within 1-2 days and usually resolves, atheroembolic renal disease has a delayed onset and renal function may not fully recover.', 2),
('dd000000-0000-0000-0000-000000000018', 'Anticoagulation can worsen cholesterol embolisation by promoting further plaque disruption, so management is supportive with cautious anticoagulant use, alongside cardiovascular risk factor optimisation.', 3),
('dd000000-0000-0000-0000-000000000019', 'Cerebral salt wasting and SIADH can both cause hyponatraemia after neurological injury (including subarachnoid haemorrhage), but are distinguished by volume status: cerebral salt wasting is hypovolaemic (with natriuresis and volume depletion), while SIADH is euvolaemic.', 1),
('dd000000-0000-0000-0000-000000000019', 'Correct identification of volume status is essential, because treatment is opposite: cerebral salt wasting requires salt and volume replacement, whereas SIADH requires fluid restriction (or occasionally vaptans).', 2),
('dd000000-0000-0000-0000-000000000019', 'Maintaining adequate intravascular volume and avoiding hyponatraemia-related complications is particularly important after subarachnoid haemorrhage because hypovolaemia can worsen cerebral vasospasm and ischaemia.', 3),
('dd000000-0000-0000-0000-000000000020', 'Severe, symptomatic hyponatraemia (seizures, reduced consciousness) is treated urgently with hypertonic saline boluses to acutely raise serum sodium and reduce cerebral oedema, regardless of the underlying cause.', 1),
('dd000000-0000-0000-0000-000000000020', 'Correction of chronic hyponatraemia should not exceed approximately 8-10 mmol/L in the first 24 hours (with lower limits in high-risk patients) to avoid osmotic demyelination syndrome.', 2),
('dd000000-0000-0000-0000-000000000020', 'If sodium correction is running ahead of the safe rate, active re-lowering strategies (desmopressin with dextrose water) may be required to prevent osmotic demyelination.', 3),
('dd000000-0000-0000-0000-000000000021', 'Novel potassium binders (patiromer, sodium zirconium cyclosilicate) enable continuation of beneficial RAAS-blocking therapy in patients with chronic hyperkalaemia, rather than requiring drug withdrawal.', 1),
('dd000000-0000-0000-0000-000000000021', 'Calcium resonium has largely fallen out of favour for chronic outpatient hyperkalaemia management due to poor tolerability and safety concerns with prolonged use.', 2),
('dd000000-0000-0000-0000-000000000021', 'Management decisions for chronic hyperkalaemia should weigh the cardiorenal benefits of RAAS blockade against the risks of hyperkalaemia, favouring strategies that preserve RAAS blockade where possible.', 3),
('dd000000-0000-0000-0000-000000000022', 'Post-pituitary surgery diabetes insipidus is a central (vasopressin-deficient) form and is confirmed by a marked concentrating response of urine osmolality to exogenous desmopressin.', 1),
('dd000000-0000-0000-0000-000000000022', 'Post-operative diabetes insipidus can follow a triphasic pattern (initial DI, then transient SIADH-like phase from ADH release from injured neurons, then potentially permanent DI), so ongoing sodium monitoring is essential even after starting desmopressin.', 2),
('dd000000-0000-0000-0000-000000000022', 'Central DI (responds to desmopressin) must be distinguished from nephrogenic DI (does not respond to desmopressin), as management differs substantially.', 3),
('dd000000-0000-0000-0000-000000000023', 'Volume depletion in hypercalcaemia of malignancy is often both a consequence (polyuria from impaired concentrating ability) and a contributor (reduced renal calcium clearance), so isotonic saline rehydration is a foundational first step.', 1),
('dd000000-0000-0000-0000-000000000023', 'Intravenous bisphosphonates are the mainstay for lowering calcium in hypercalcaemia of malignancy but have a delayed onset of maximal effect (2-4 days), so supportive measures (fluids, calcitonin for very rapid but short-lived effect) may bridge the interval.', 2),
('dd000000-0000-0000-0000-000000000023', 'Renal impairment influences bisphosphonate dosing and choice (e.g. denosumab may be preferred over bisphosphonates in significant renal impairment, as it is not renally cleared).', 3),
('dd000000-0000-0000-0000-000000000024', 'Refeeding syndrome occurs when carbohydrate reintroduction after prolonged catabolic starvation triggers an insulin surge, causing severe intracellular shifts of phosphate, potassium, and magnesium with dangerous extracellular depletion.', 1),
('dd000000-0000-0000-0000-000000000024', $x$Prevention and management require starting feeding cautiously at a low rate in at-risk patients (chronic malnutrition, alcohol use disorder, prolonged fasting), with proactive electrolyte monitoring and replacement, plus thiamine to prevent Wernicke's encephalopathy.$x$, 2),
('dd000000-0000-0000-0000-000000000024', 'Severe hypophosphataemia in refeeding syndrome can cause cardiac and respiratory muscle weakness and arrhythmia, making urgent replacement and cardiac monitoring essential.', 3),
('dd000000-0000-0000-0000-000000000025', 'Tolvaptan slows renal cyst growth and eGFR decline in ADPKD patients with evidence of rapid progression, but requires close monitoring for hepatotoxicity, particularly in the first 18 months of therapy.', 1),
('dd000000-0000-0000-0000-000000000025', 'Aquaresis-related side effects of tolvaptan (polyuria, polydipsia, risk of hypernatraemia/dehydration) require patient education and monitoring alongside liver function tests.', 2),
('dd000000-0000-0000-0000-000000000025', 'Patient selection for tolvaptan is based on evidence of rapidly progressive disease (e.g. imaging classification of total kidney volume, rate of eGFR decline), not simply a diagnosis of ADPKD alone.', 3),
('dd000000-0000-0000-0000-000000000026', 'Intracranial aneurysm screening in ADPKD is targeted, not universal: indicated for patients with a family history of aneurysm or subarachnoid haemorrhage, prior personal history, high-risk occupations, or before major elective surgery.', 1),
('dd000000-0000-0000-0000-000000000026', 'MR angiography is the preferred screening modality, avoiding iodinated contrast and ionising radiation exposure.', 2),
('dd000000-0000-0000-0000-000000000026', $x$A family history of subarachnoid haemorrhage or known aneurysm in a first-degree relative substantially raises an individual ADPKD patient's own risk, justifying screening even when asymptomatic.$x$, 3),
('dd000000-0000-0000-0000-000000000027', 'Alport syndrome results from mutations in type IV collagen genes (most commonly X-linked COL4A5), causing an abnormal glomerular basement membrane, sensorineural hearing loss, and ocular abnormalities such as anterior lenticonus.', 1),
('dd000000-0000-0000-0000-000000000027', $x$A small but important subset of Alport syndrome transplant recipients develop anti-GBM (Goodpasture's-like) disease in the graft, because their native immune system has never encountered the normal alpha-5(IV) collagen chain now present in the donor kidney.$x$, 2),
('dd000000-0000-0000-0000-000000000027', $x$Electron microscopy in Alport syndrome classically shows basement membrane thinning, splitting, and lamellation ('basket-weave' appearance), distinguishing it from other hereditary and acquired glomerulopathies.$x$, 3),
('dd000000-0000-0000-0000-000000000028', 'Fabry disease is an X-linked lysosomal storage disorder caused by alpha-galactosidase A deficiency, leading to globotriaosylceramide accumulation in multiple organs including the kidney, heart, and nervous system.', 1),
('dd000000-0000-0000-0000-000000000028', $x$Classic features include acroparaesthesias, angiokeratomas, corneal verticillata, and progressive proteinuric kidney disease, with podocyte lipid inclusions ('zebra bodies') seen on electron microscopy of renal biopsy.$x$, 2),
('dd000000-0000-0000-0000-000000000028', 'Enzyme replacement therapy (or oral chaperone therapy for amenable mutations) is disease-specific treatment aimed at slowing progression of renal, cardiac, and neurological manifestations, and should be initiated once organ involvement is demonstrated.', 3),
('dd000000-0000-0000-0000-000000000029', 'UMOD-related autosomal dominant tubulointerstitial kidney disease causes slowly progressive CKD with a characteristic early, disproportionate hyperuricaemia and gout, distinct from typical age-related gout seen with declining GFR from other causes.', 1),
('dd000000-0000-0000-0000-000000000029', 'Unlike ADPKD, UMOD-related disease does not cause significant renal cyst formation, and kidneys are usually normal-sized or small on imaging despite a similarly dominant inheritance pattern and multi-generational family history of renal failure.', 2),
('dd000000-0000-0000-0000-000000000029', 'Recognising non-cystic genetic tubulointerstitial diseases is important because management (including urate-lowering therapy considerations) and genetic counselling differ from ADPKD despite superficially similar family histories.', 3),
('dd000000-0000-0000-0000-000000000030', 'Renal angiomyolipomas larger than 3-4 cm, or with an associated aneurysm, carry significant risk of spontaneous haemorrhage (Wunderlich syndrome) and warrant pre-emptive intervention even when asymptomatic.', 1),
('dd000000-0000-0000-0000-000000000030', 'Selective embolisation is the standard acute intervention for reducing haemorrhage risk, while mTOR inhibitors (e.g. everolimus) provide durable size reduction by targeting the underlying tuberous sclerosis-related pathway dysregulation.', 2),
('dd000000-0000-0000-0000-000000000030', 'Nephron-sparing strategies are preferred in tuberous sclerosis-associated angiomyolipomas because lesions are frequently multiple and bilateral, making preservation of renal parenchyma important for long-term renal function.', 3),
('dd000000-0000-0000-0000-000000000031', 'Indications for immunosuppressive therapy in membranous nephropathy include persistent nephrotic syndrome or declining renal function despite an adequate trial (typically at least 6 months) of maximised conservative therapy (RAAS blockade, salt restriction).', 1),
('dd000000-0000-0000-0000-000000000031', 'Rituximab has become a preferred first-line immunosuppressive option for PLA2R-associated membranous nephropathy in many guidelines, offering comparable efficacy to older regimens with a more favourable safety profile, particularly for moderate-risk disease.', 2),
('dd000000-0000-0000-0000-000000000031', 'Serial anti-PLA2R antibody titres can be used to monitor immunological activity and response to treatment, often preceding changes in proteinuria.', 3),
('dd000000-0000-0000-0000-000000000032', 'Optimised supportive therapy for IgA nephropathy now includes maximised RAAS blockade combined with an SGLT2 inhibitor, given evidence of additive renoprotective effect.', 1),
('dd000000-0000-0000-0000-000000000032', 'Targeted-release budesonide acts locally on gut-associated lymphoid tissue thought to generate pathogenic galactose-deficient IgA1, reducing proteinuria and eGFR decline with less systemic toxicity than conventional corticosteroids.', 2),
('dd000000-0000-0000-0000-000000000032', 'Systemic immunosuppression (corticosteroids, cyclophosphamide) in IgA nephropathy is generally reserved for more aggressive phenotypes (e.g. crescentic disease, rapidly declining eGFR), where the risk-benefit balance differs from stable, low-risk disease.', 3),
('dd000000-0000-0000-0000-000000000033', 'The PEXIVAS trial found no overall reduction in death or end-stage kidney disease with routine plasma exchange added to standard immunosuppression in ANCA-associated vasculitis with severe renal involvement.', 1),
('dd000000-0000-0000-0000-000000000033', 'Plasma exchange retains a selectively considered role in severe, hypoxaemic diffuse alveolar (pulmonary) haemorrhage in ANCA-associated vasculitis, used alongside, not instead of, standard immunosuppressive induction.', 2),
('dd000000-0000-0000-0000-000000000033', 'Rituximab has demonstrated non-inferiority (and in some analyses, superiority for relapsing disease) to cyclophosphamide for induction therapy in ANCA-associated vasculitis, and is now widely used as a preferred induction agent.', 3),
('dd000000-0000-0000-0000-000000000034', 'Mycophenolate mofetil combined with corticosteroids is an established, guideline-recommended induction regimen for proliferative (class III/IV) lupus nephritis, with efficacy comparable to cyclophosphamide-based regimens but generally better tolerability.', 1),
('dd000000-0000-0000-0000-000000000034', $x$Cyclophosphamide's gonadotoxicity is an important consideration when choosing induction therapy in women of childbearing age, favouring mycophenolate mofetil where appropriate.$x$, 2),
('dd000000-0000-0000-0000-000000000034', 'Hydroxychloroquine should be continued as background therapy in essentially all SLE patients regardless of the specific induction regimen chosen for active lupus nephritis.', 3),
('dd000000-0000-0000-0000-000000000035', 'Anti-GBM disease (Goodpasture syndrome) is caused by autoantibodies against the alpha-3 chain of type IV collagen, producing linear IgG deposition on glomerular basement membrane and, when antibodies also target alveolar basement membrane, pulmonary haemorrhage.', 1),
('dd000000-0000-0000-0000-000000000035', 'Urgent combination therapy with plasma exchange (to remove circulating pathogenic antibody), corticosteroids, and cyclophosphamide is the standard of care, and treatment should not be delayed for biopsy confirmation when clinical suspicion is high and the presentation is severe.', 2),
('dd000000-0000-0000-0000-000000000035', 'Prognosis for renal recovery in anti-GBM disease is closely related to the creatinine at presentation and the proportion of glomeruli with crescents, but treatment is still generally pursued urgently given the severity of pulmonary involvement and the narrow treatment window.', 3),
('dd000000-0000-0000-0000-000000000036', 'Primary FSGS has a significant risk of early, often severe recurrence after renal transplantation, thought to be mediated by a circulating permeability factor rather than an alloimmune (rejection) mechanism.', 1),
('dd000000-0000-0000-0000-000000000036', 'Plasmapheresis, sometimes combined with rituximab and/or high-dose corticosteroids, is the standard approach to treating recurrent FSGS, aiming to remove or reduce the putative permeability factor.', 2),
('dd000000-0000-0000-0000-000000000036', 'Distinguishing recurrent primary disease from graft rejection on biopsy is essential, as the treatment approaches differ substantially despite both potentially causing early graft dysfunction.', 3),
('dd000000-0000-0000-0000-000000000037', 'Acute T-cell mediated (cellular) rejection is characterised histologically by interstitial inflammation and tubulitis, and is first-line treated with pulsed intravenous corticosteroids for milder grades.', 1),
('dd000000-0000-0000-0000-000000000037', 'Antibody-mediated rejection (typically associated with C4d positivity and donor-specific antibodies) is managed differently, with plasma exchange, IVIG, and/or rituximab rather than corticosteroids alone.', 2),
('dd000000-0000-0000-0000-000000000037', 'A therapeutic calcineurin inhibitor trough level does not exclude rejection; biopsy findings determine the type and severity of rejection and guide specific treatment.', 3),
('dd000000-0000-0000-0000-000000000038', 'Antibody-mediated rejection is characterised by peritubular capillaritis and/or glomerulitis, C4d positivity in peritubular capillaries, and detectable donor-specific antibodies, distinguishing it from T-cell mediated cellular rejection.', 1),
('dd000000-0000-0000-0000-000000000038', 'Standard treatment for antibody-mediated rejection combines plasma exchange (or immunoadsorption) with intravenous immunoglobulin, often with rituximab, targeting different components of the antibody-mediated pathway.', 2),
('dd000000-0000-0000-0000-000000000038', 'Refractory antibody-mediated rejection may prompt consideration of additional agents (e.g. bortezomib, complement inhibitors such as eculizumab) in specialist transplant centres.', 3),
('dd000000-0000-0000-0000-000000000039', 'BK virus-associated nephropathy results from viral reactivation under the burden of immunosuppression, and screening (urine decoy cells, plasma BK PCR) allows early detection before overt graft dysfunction develops.', 1),
('dd000000-0000-0000-0000-000000000039', 'The primary treatment strategy is graded reduction of overall immunosuppression (often antimetabolite first) to restore host immune control of viral replication, balanced against rejection risk.', 2),
('dd000000-0000-0000-0000-000000000039', 'Unlike CMV, there is no antiviral agent with clearly established efficacy specifically for BK virus, distinguishing management approaches for these two common post-transplant viral complications.', 3),
('dd000000-0000-0000-0000-000000000040', 'CMV donor-positive/recipient-negative serostatus mismatch represents the highest-risk group for CMV disease post-transplant, and requires either universal prophylaxis or close virological surveillance with pre-emptive treatment strategies.', 1),
('dd000000-0000-0000-0000-000000000040', 'CMV disease (symptomatic infection with organ involvement, such as colitis, alongside viraemia) requires treatment-dose antiviral therapy (valganciclovir or ganciclovir), which differs from prophylactic dosing used to prevent infection.', 2),
('dd000000-0000-0000-0000-000000000040', 'Judicious, temporary reduction of antimetabolite immunosuppression can aid immune clearance of CMV during treatment of established disease, balanced against rejection risk.', 3),
('dd000000-0000-0000-0000-000000000041', 'Calcineurin inhibitor toxicity classically shows isometric tubular vacuolisation and arteriolar hyalinosis on biopsy, in contrast to the interstitial inflammation and tubulitis of cellular rejection or the capillaritis/C4d positivity of antibody-mediated rejection.', 1),
('dd000000-0000-0000-0000-000000000041', 'A supratherapeutic trough level supports a diagnosis of calcineurin inhibitor toxicity, though biopsy remains important since toxicity and rejection can occasionally coexist or trough levels can be misleading.', 2),
('dd000000-0000-0000-0000-000000000041', 'Management of calcineurin inhibitor toxicity is dose reduction with close monitoring, as the nephrotoxic changes are often at least partially reversible if identified and corrected promptly.', 3),
('dd000000-0000-0000-0000-000000000042', 'New-onset diabetes after transplantation is a recognised complication of immunosuppressive therapy, with tacrolimus and corticosteroids being major contributors, and tacrolimus generally considered more diabetogenic than ciclosporin.', 1),
('dd000000-0000-0000-0000-000000000042', 'Management balances glycaemic control (lifestyle measures, glucose-lowering therapy) against the competing need to maintain adequate immunosuppression to prevent rejection, so immunosuppression adjustments are made cautiously.', 2),
('dd000000-0000-0000-0000-000000000042', 'Post-transplant diabetes mellitus carries important long-term implications for cardiovascular risk and graft/patient survival, warranting proactive screening and management rather than a watch-and-wait approach.', 3),
('dd000000-0000-0000-0000-000000000043', 'Delayed graft function is most commonly caused by ischaemia-reperfusion injury (a form of acute tubular necrosis), with risk increased by donor instability, prolonged cold ischaemic time, and other donor/recipient risk factors.', 1),
('dd000000-0000-0000-0000-000000000043', 'Doppler ultrasound showing preserved vascular flow without thrombosis or obstruction helps exclude surgical/vascular causes of graft dysfunction, supporting a diagnosis of ischaemia-reperfusion-related delayed graft function.', 2),
('dd000000-0000-0000-0000-000000000043', 'Management is largely supportive, including dialysis if needed, avoidance of additional nephrotoxic exposures, and judicious immunosuppression dosing, since tubular recovery typically occurs over days to a few weeks.', 3),
('dd000000-0000-0000-0000-000000000044', 'Distal (type 1) renal tubular acidosis is characterised by impaired distal tubular hydrogen ion secretion, producing a hypokalaemic, normal-anion-gap metabolic acidosis with an inappropriately alkaline urine pH (>5.5) despite systemic acidaemia.', 1),
('dd000000-0000-0000-0000-000000000044', $x$Distal RTA is associated with autoimmune conditions such as Sjogren's syndrome, and characteristically causes nephrocalcinosis and calcium phosphate stone formation due to increased urinary calcium excretion and reduced citrate excretion in an alkaline urine environment.$x$, 2),
('dd000000-0000-0000-0000-000000000044', 'Alkali replacement (potassium citrate is often preferred as it addresses both acidosis and hypokalaemia while providing citrate to reduce stone risk) is the mainstay of long-term management.', 3),
('dd000000-0000-0000-0000-000000000045', 'Fanconi syndrome reflects generalised proximal tubular dysfunction, causing combined losses of glucose, phosphate, urate, amino acids, and bicarbonate, distinguishing it from isolated distal tubular acidification defects.', 1),
('dd000000-0000-0000-0000-000000000045', 'Multiple myeloma can cause proximal tubulopathy through direct nephrotoxic effects of filtered free light chains on proximal tubular cells, in addition to other myeloma-related kidney injuries such as cast nephropathy.', 2),
('dd000000-0000-0000-0000-000000000045', 'Proximal (type 2) RTA typically causes a milder degree of acidosis than distal RTA because distal acidification mechanisms remain intact, though the broader Fanconi picture (multiple solute losses) is the key distinguishing clue here.', 3),
('dd000000-0000-0000-0000-000000000046', 'Type 4 RTA, most commonly from hyporeninaemic hypoaldosteronism in diabetic nephropathy, causes hyperkalaemia with only a mild hyperchloraemic metabolic acidosis, distinguishing it from the hypokalaemic types 1 and 2 RTA.', 1),
('dd000000-0000-0000-0000-000000000046', 'The hyperkalaemia in type 4 RTA itself impairs ammoniagenesis in the proximal tubule, contributing to the mild acidosis seen, in addition to reduced aldosterone-driven distal sodium reabsorption and hydrogen/potassium secretion.', 2),
('dd000000-0000-0000-0000-000000000046', 'Management focuses on potassium control (dietary restriction, loop diuretics, avoidance of exacerbating medications such as ACE inhibitors/ARBs/NSAIDs/potassium-sparing diuretics where possible) rather than alkali therapy as the primary strategy.', 3),
('dd000000-0000-0000-0000-000000000047', 'Bartter syndrome mimics chronic loop diuretic use (defect in the Na-K-2Cl co-transporter of the thick ascending limb), causing hypokalaemic metabolic alkalosis, normotension, secondary hyperreninaemic hyperaldosteronism, and hypercalciuria with nephrocalcinosis.', 1),
('dd000000-0000-0000-0000-000000000047', 'Gitelman syndrome mimics thiazide diuretic use (distal convoluted tubule NaCl co-transporter defect) and is distinguished from Bartter syndrome by hypocalciuria and prominent hypomagnesaemia, with typically milder, later-presenting symptoms.', 2),
('dd000000-0000-0000-0000-000000000047', 'Normal blood pressure with markedly elevated renin and aldosterone in a hypokalaemic, alkalotic patient points towards a renal salt-losing tubulopathy (Bartter or Gitelman syndrome) rather than a primary mineralocorticoid excess or channel gain-of-function disorder.', 3),
('dd000000-0000-0000-0000-000000000048', 'Gitelman syndrome results from a thiazide-sensitive NaCl co-transporter defect in the distal convoluted tubule, causing hypokalaemic metabolic alkalosis with characteristic hypomagnesaemia and hypocalciuria, and generally normal blood pressure.', 1),
('dd000000-0000-0000-0000-000000000048', 'Hypomagnesaemia in Gitelman syndrome can perpetuate renal potassium wasting, so magnesium repletion is often necessary before hypokalaemia can be effectively and durably corrected.', 2),
('dd000000-0000-0000-0000-000000000048', 'Hypocalciuria in Gitelman syndrome (versus hypercalciuria in Bartter syndrome) is a key distinguishing biochemical feature between these two salt-losing tubulopathies that otherwise share overlapping clinical features.', 3),
('dd000000-0000-0000-0000-000000000049', 'Liddle syndrome is caused by a gain-of-function mutation in the epithelial sodium channel (ENaC), producing a clinical picture that mimics mineralocorticoid excess (hypertension, hypokalaemic alkalosis) despite suppressed renin and aldosterone.', 1),
('dd000000-0000-0000-0000-000000000049', 'Because the defect lies in the channel itself rather than in aldosterone signalling, mineralocorticoid receptor antagonists (spironolactone) are ineffective, while direct epithelial sodium channel blockers (amiloride, triamterene) are the treatment of choice.', 2),
('dd000000-0000-0000-0000-000000000049', 'A family history of early-onset hypertension with hypokalaemia and suppressed renin/aldosterone should prompt consideration of Liddle syndrome as an inherited channelopathy rather than assuming a purely acquired cause of hypertension.', 3),
('dd000000-0000-0000-0000-000000000050', 'Cystinuria is an autosomal recessive disorder of defective proximal tubular (and intestinal) reabsorption of cystine and dibasic amino acids, causing recurrent, radiolucent, hexagonal-crystal stones typically presenting from a young age with a positive family history.', 1),
('dd000000-0000-0000-0000-000000000050', 'First-line conservative management includes high fluid intake and urinary alkalinisation (e.g. with potassium citrate) to increase cystine solubility, since cystine solubility rises sharply at higher urine pH.', 2),
('dd000000-0000-0000-0000-000000000050', 'When conservative measures are insufficient, thiol-based chelating agents (tiopronin, D-penicillamine) bind cysteine to form a more soluble compound, reducing further stone formation; tiopronin is generally preferred due to fewer adverse effects than D-penicillamine.', 3);
